        'intros' => [
            'custom_fields' => 'Створюйте додаткові відомості, потрібні певному виду заявок - наприклад, дату початку й ім\'я користувача для нового працівника - і вибирайте, до яких типів заявок належить кожне. Кожне поле саме визначає, чи має воно бути заповнене під час реєстрації заявки, під час її закриття чи в обох випадках, і чи запитують його в ініціатора на порталі.',
            'checklists' => 'Чек-лист може позначати кроки як обов\'язкові. Це визначає, що відбувається, якщо хтось закриває заявку до того, як ці кроки позначено виконаними.',
            'mandatory_fields' => 'Оберіть, які поля заявки має бути заповнено перед закриттям, і що відбувається, коли хтось закриває заявку з порожнім хоча б одним із них. Правило діє скрізь, де можна закрити заявку: на екрані заявки, у масових діях, через REST API та в процесах.',
            'departments' => 'Відділи групують заявки та спрямовують їх до потрібної частини вашої організації — створіть ті, які ваша служба підтримки використовує для категоризації та призначення роботи.',
            'teams' => 'Команди визначають, до яких відділів мають доступ аналітики. Призначте відділи командам, а потім призначте аналітиків командам, щоб керувати їхнім доступом.',
            'ticket_types' => 'Типи заявок класифікують, чим є запит (наприклад, інцидент, запит на обслуговування) — визначте типи, які аналітики можуть встановлювати на заявці.',
            'ticket_origins' => 'Джерела заявок фіксують, як надійшла заявка (наприклад, електронна пошта, телефон, портал) — визначте джерела, з яких можуть обирати аналітики.',
            'mailboxes' => 'Поштові скриньки з\'єднують FreeITSM з обліковими записами електронної пошти, щоб вхідні повідомлення ставали заявками, а відповіді надсилалися назад — додайте та автентифікуйте ті, за якими стежить ваша служба підтримки.',
            'privacy' => 'Заявка містить не лише вашу переписку з тим, хто її створив. Пересилання постачальнику або копіювання колезі додає це повідомлення до тієї самої заявки — і його відповідь теж потрапляє туди. Це визначає, скільки з цього бачить ініціатор у порталі самообслуговування.',
            'indexing' => 'Текст усередині вкладень читається, щоб його можна було шукати. Файли Word, Excel, PowerPoint і звичайний текст FreeITSM читає самостійно одразу після надходження. PDF, старіші файли Office та скановані документи потребують окремої служби читання документів — налаштуйте її в <strong>Система &rarr; Інтеграції &rarr; Apache Tika</strong> — і оскільки їх опрацювання триває значно довше, вони читаються у фоновому режимі. Ці два перемикачі визначають, коли відбувається ця фонова робота.',
            'merge_behaviour' => 'Коли дві заявки виявляються тим самим, аналітик може їх об\'єднати. Ці налаштування визначають, що відбувається з номерами заявок, які мають ваші ініціатори, і що стається з переписками. Вони застосовуються до всіх — об\'єднання змінює те, що бачить клієнт, тож двоє аналітиків на одній поштовій скриньці не повинні мати можливість вирішувати це по-різному.',
            'reply_templates' => 'Готові відповіді, які ваші аналітики можуть вставляти у відповідь замість того, щоб набирати їх заново. Тут — спільні шаблони, які бачить уся команда; власні приватні шаблони аналітика зберігаються з вікна відповіді і тут не показані.',
            'rota_shifts' => 'Зміни — це шаблони робочого графіка (наприклад, рання, пізня, чергування), які призначаються аналітикам у графіку персоналу — визначте їх тут перед побудовою графіка.',
            'analysts' => 'Аналітики — це персонал, який входить у систему та працює із заявками — додавайте їх, скидайте паролі та призначайте командам, щоб керувати їхнім доступом.',
            'general' => 'Загальні налаштування керують поведінкою заявок - повторним відкриттям, відкладенням і тим, як довго показуються повідомлення та гілки.',
            'statuses' => 'Стани процесу, в яких може перебувати заявка. Статуси, позначені як <em>Закрито</em>, вважаються кінцевими — їх використовують звіти, лічильники Watchtower та автоматичне встановлення дати й часу закриття під час призначення. Рівно один статус є типовим для нових заявок.',
            'priorities' => 'Рівні пріоритету, що показуються на заявках. Рівно один пріоритет є типовим для нових заявок.',
            'rota_locations' => 'Де працює кожен аналітик у певний день — використовується графіком персоналу та показується кольоровим значком на кожному записі. Рівно одне місце є типовим для нових записів графіка.',
            'email_templates' => 'Автоматичні відповіді електронною поштою, що надсилаються подіями заявки. Для кожної події використовується лише перший активний шаблон.',
        ],
        'messaging' => [
            'channels_heading' => 'Канали обміну повідомленнями',
            'channels_intro' => 'Дозвольте клієнтам спілкуватися з аналітиком через WhatsApp — кожне повідомлення стає заявкою, так само як і електронна пошта. Додайте канал нижче, а потім вставте його <strong>webhook URL</strong> у налаштуваннях постачальника (Twilio або Meta), щоб вхідні повідомлення надходили до цієї інсталяції.',
            'base_url_label' => '<strong>Публічна базова адреса</strong>',
            'base_url_placeholder' => 'https://your-domain.com  (або ваша адреса ngrok під час тестування)',
            'base_url_help' => 'Адреса, яку постачальники використовують, щоб звертатися до цієї інсталяції. Вкажіть її — і webhook URL нижче будуть готові до копіювання. Залиште порожнім, щоб використовувати адресу, з якої ви зараз переглядаєте сторінку. Тестуєте локально? Запустіть <code>ngrok http 80</code> і вставте адресу <code>https://…ngrok-free.dev</code>, яку він виведе.',
            'templates_heading' => 'Шаблони повідомлень',
            'templates_intro' => 'Попередньо схвалені шаблони дозволяють аналітику відповідати <strong>після завершення 24-годинного вікна</strong>. WhatsApp дозволяє вільний текст лише протягом 24 годин після останнього повідомлення клієнта; поза цим періодом можна надіслати лише шаблон, схвалений Meta/Twilio. Створіть і схваліть шаблон у постачальника, а потім додайте його опис тут (із заповнювачами <code>{{1}}</code>, <code>{{2}}</code>), щоб аналітики могли обрати й заповнити його.',
        ],
