            'notifs_heading' => 'Сповіщення про порушення',
            'notifs_info' => '<strong style="display:block;margin-bottom:6px;font-size:14px;">Як працюють правила сповіщень</strong>Кожне правило складається з чотирьох частин: <strong>область дії</strong>, <strong>тригер</strong>, <strong>ціль</strong> і список <strong>отримувачів</strong>.<br><br><strong>Область дії</strong> може бути або <em>За замовчуванням</em> (правило застосовується до заявок у кожному відділі), або <em>конкретний відділ</em> (правило застосовується лише до заявок цього відділу).<br>Коли заявка оцінюється, система спочатку шукає правило, що відповідає її відділу &mdash; якщо таке є, воно перемагає, а правило за замовчуванням ігнорується. Якщо правила для відділу немає, використовується правило за замовчуванням. Так можна задати розумні значення за замовчуванням, що охоплюють кожен відділ, а потім виокремити винятки там, де в команди інші вимоги до ескалації.<br><br><strong>Тригер</strong> — це або <em>Попередження</em> (заявка перетнула поріг попередження &mdash; наближається можливе порушення), або <em>Порушення</em> (заявка вже перевищила ціль SLA &mdash; фактичне порушення). Кожен варіант — окреме правило, тож можна сповіщати різних людей про попередження та про порушення.<br><br><strong>Ціль</strong> — це який годинник SLA відстежувати &mdash; <em>Реагування</em>, <em>Вирішення</em> або <em>Обидва</em>.<br><br><strong>Отримувачі</strong> можуть бути будь-якою комбінацією: поточний виконавець заявки, кожен аналітик у командах відділу заявки, один названий аналітик та/або список довільних електронних адрес (корисно для спільних скриньок або поштових містків Slack/Teams).<br><br><strong style="color:var(--warning-text, #92400e);">Немає правил = немає листів.</strong> Навіть якщо заявка порушує SLA, нічого не спрацює, доки ви не додасте хоча б одне правило (почніть із пари «За замовчуванням: Попередження + Порушення», щоб отримати покриття для всього).',
            'notifs_dedup' => 'Кожна заявка надсилає щонайбільше один лист на ціль на тригер &mdash; обробник cron відстежує, що вже надіслано, щоб уникнути дублювання.',
