            'reopen_label' => 'Повторне відкриття',
            'reopen_toggle' => 'Повторно відкривати закриту заявку, коли ініціатор відповідає',
            'snooze_hour_label' => 'Початок робочого дня',
            'snooze_hour_help' => 'Час, коли повертається заявка, відкладена до «Завтра» чи «Наступного тижня». Визначається за власним часовим поясом кожного аналітика, тож команда, розкидана по поясах, отримує власний ранок.',
            'collapse_heading' => 'Довгі повідомлення',
            'collapse_desc' => 'Довгі листи ховають те, заради чого відкрили заявку. Повідомлення, довші за наведену нижче межу, скорочуються з посиланням «Показати більше». Нічого не видаляється — повне повідомлення завжди за один клік.',
            'collapse_enabled_label' => 'Скорочувати довгі повідомлення',
            'collapse_lines_label' => 'Скорочувати повідомлення довші за приблизно',
            'collapse_lines_help' => 'рядків. Повідомлення, що лише трохи перевищує межу, не чіпається, тож посилання не з\'являється заради двох зайвих слів.',
            'collapse_newest_label' => 'Завжди показувати найновіше повідомлення повністю',
