            'collapse_quoted_label' => 'Скорочувати цитовану історію',
            'collapse_quoted_help' => 'Коротка відповідь із довгим цитованим ланцюжком під нею коротка за будь-якою кількістю рядків, але все одно нечитабельна, тож цитована історія скорочується окремо.',
            'collapse_remember_label' => 'Пам\'ятати, що я відкривав',
