            'group_older_label' => 'Згортати старіші повідомлення',
            'group_older_help' => 'Понад кількість, вказану нижче, старіші повідомлення згортаються в один рядок, який можна розгорнути. Довга заявка — це інша проблема, ніж довге повідомлення.',
            'group_show_label' => 'Залишати розгорнутими стільки останніх повідомлень',
            'flag_duplicates_label' => 'Позначати повідомлення, які вже надходили раніше',
            'flag_duplicates_help' => 'Повторне надсилання, дубльована доставка чи повернене повідомлення з оригіналом усередині згортається з приміткою, якому повідомленню воно відповідає. Нічого не видаляється.',
            'team_folders_heading' => 'Теки команд',
