            'team_folders_all' => 'Кожну команду',
            'team_folders_mine' => 'Лише команди, до яких вони належать',
            'team_folders_help' => 'Змінює лише список тек - ніхто не втрачає із поля зору жодну заявку. Команда, у якій є заявки, видимі аналітику, усе одно показується, тож підсумки в теках сходяться. Адміністратори завжди бачать кожну команду.',
            'watch_heading' => 'Стеження за заявками',
            'watch_help' => 'Про що повідомляють спостерігачів заявки. Особисті налаштування сповіщень кожного спостерігача діють додатково.',
            'watch_inactive_label' => 'Коли спостерігача деактивовано',
