            'watch_inactive_help' => 'Деактивованого аналітика ніколи ні про що не повідомляють. «Більше не повідомляти» ховає його стеження і повертає, якщо аналітика знову зробити активним; «Вилучити» видаляє його, коли аналітика деактивовано. Вилучення діє з моменту збереження.',
            'watch_event_ticket_reply_received' => 'Ініціатор відповідає',
