            'watch_event_sla_breached' => 'Порушено цільовий термін SLA',
            'ai_heading' => 'Засоби читання на основі AI',
            'ai_desc' => 'Необов\'язкові й вимкнені, доки ви їх не увімкнете: на відміну від решти цієї сторінки, вони використовують вашого власного постачальника AI й коштують грошей за кожне використання. Постачальник, модель та API-ключ налаштовуються один раз на вкладці «Очищення відповіді». Ніщо, написане AI, ніколи не замінює заявку — обговорення завжди залишається на місці, повністю.',
            'ai_summary_label' => 'Показувати короткий підсумок AI вгорі кожної заявки',
            'ai_summary_help' => 'Кілька рядків про поточний стан заявки, які пишуться на запит і підтримуються в актуальному стані. Завжди видно, коли підсумок написано, скільки він охопив і наскільки обговорення просунулося відтоді. Зберігається кожна версія, тож гірший підсумок ніколи не замінює кращий.',
            'ai_auto_label' => 'Оновлювати автоматично після такої кількості нових повідомлень',
            'ai_auto_help' => '0 означає ніколи — тоді єдиний спосіб оновити це кнопкою «Оновити», і плата не стягується, доки хтось не запросить оновлення. Оновлення відбувається лише тоді, коли аналітик відкриває заявку, тож завантажена черга, яку ніхто не читає, нічого не коштує.',
            'ai_max_label' => 'Скільки повідомлень читати',
            'ai_max_help' => 'Наскільки далеко назад читає підсумок. Довшу заявку читають з найновішого кінця, і підсумок про це повідомляє, а не описує початок, якого не бачив.',
            'ai_notes_label' => 'Дозволити читати внутрішні нотатки',
            'ai_notes_help' => 'Внутрішні нотатки часто містять те, що справді пробували зробити. У будь-якому разі вони бачать лише персонал — підсумок ніколи не показується ініціатору — але вимкніть це, якщо нотатки вашої служби підтримки містять те, що не повинно виходити за її межі.',
            'ai_read_label' => 'Пропонувати «Прочитати» в заявці',
            'ai_confidential_label' => 'Конфіденційні заявки й AI',
            'ai_confidential_block' => 'Ніколи не надсилати їх до AI (рекомендовано)',
            'ai_confidential_allow' => 'Ставитися до них як до будь-якої іншої заявки',
            'ai_confidential_help' => 'Охоплює кожну функцію AI, що читає заявку: підсумок, «Прочитати», очищення відповіді, запит до ШІ, підсумки злиття, статті бази знань, підсумки каналів, аналіз проблем і бота кімнати війни. Конфіденційна заявка або не надсилається, або - коли одночасно читається багато заявок - пропускається чи показується лише за номером.',
            'ai_read_help' => 'Кнопка, яка читає всю заявку й коротко розповідає вам про неї: що сталося, що ще не вирішено і що робити далі. Запитується й читається один раз, ніде не зберігається.',
            'reopen_help' => 'Застосовується всюди, звідки може повернутися ініціатор — портал самообслуговування, відповідь на ваш лист-сповіщення, WhatsApp чи вебчат. Заявка повертається до вашого першого відкритого статусу. Стосується лише заявок у статусі, позначеному як закритий (які саме — вказується в розділі «Статуси»).',
