            'always_visible_note' => '<strong>Завжди видимі ініціатору:</strong> його власні повідомлення та будь-яка відповідь, адресована йому. <strong>Ніколи не видимі:</strong> внутрішні нотатки — вони приховані від порталу незалежно від цього налаштування. Повідомлення у WhatsApp і вебчаті показуються завжди, оскільки ці розмови за визначенням ведуться між ініціатором і вашою службою підтримки.',
