        'reply_cleanup' => [
            'intro1' => 'Коли аналітик вводить чорновий варіант відповіді у вікні складання заявки, кнопка <strong>✨ Очистити</strong> переформатує його у належно оформлений лист — додасть привітання «Шановний(-а) [ім\'я],», виправить граматику, застосує обраний нижче тон і завершить фразою «З повагою,». Вона <strong>не</strong> вигадуватиме технічні деталі й не наповнюватиме текст зайвим.',
            'intro2' => 'Ця функція використовує власний API-ключ Anthropic (окремий від AI для RFP та AI бази знань), тож її використання відображається окремим рядком на панелі виставлення рахунків Anthropic.',
