        'csat_tab' => [
            'intro1' => 'Коли заявку закрито, надсилайте ініціатору короткий лист-опитування з проханням оцінити досвід від 1&ndash;5. Відповіді фіксуються за аналітиком, який закрив заявку, тож можна отримувати тенденції CSAT по кожному аналітику; вони також відображаються як віджет на панелі керування.',
            'intro2' => 'Лист-опитування налаштовується в розділі <a href="#" onclick="event.preventDefault();switchTab(\'email-templates\');">Шаблони листів</a> &mdash; створіть шаблон з подією <strong>Опитування CSAT</strong> і вставте <code>[csat_link]</code> у текст, щоб додати одноразове посилання для оцінки.',
