            'mode_manual_help' => 'Аналітики натискають <em>Відгук</em> на панелі інструментів заявки, коли хочуть запитати.',
            'delay_help' => 'Скільки хвилин чекати після закриття перед надсиланням. <code>0</code> = одразу. Корисно, якщо потрібно, щоб користувач переконався, що виправлення справді спрацювало, перш ніж його попросять оцінити.',
            'reminder' => 'Надіслати одне нагадування, якщо на опитування не відповіли',
            'reminder_hours' => 'Нагадати через (годин)',
            'reminder_help' => 'Щонайбільше одне нагадування електронною поштою з тим самим посиланням - тож спрацює будь-який лист, а збережеться лише одна оцінка. Нагадування отримують лише опитування, надіслані електронною поштою, чи то під час закриття, чи кнопкою <strong>Відгук</strong>. Не надсилається, якщо заявку знову відкрито або вона в кошику на момент нагадування. Використовує шаблон листа <strong>Нагадування CSAT</strong>, якщо він у вас є, інакше знову шаблон опитування. Надсилається фоновим завданням <em>Відкладені опитування задоволеності та нагадування</em>. Увімкнення цього не нагадує про старі опитування: лише про ті, чий час нагадування настане відтепер.',
            'one_per_ticket' => 'Одне опитування на заявку',
            'one_per_ticket_help' => 'Якщо ввімкнено, повторно відкрита й знову закрита заявка отримає нове опитування лише тоді, коли аналітик запустить його вручну &mdash; це запобігає спаму опитуваннями для нестабільної заявки.',
            'in_channel' => 'Запитувати чат-клієнтів у їхньому чаті',
            'in_channel_help' => 'Клієнта, який написав у WhatsApp, Telegram, Slack, Teams або Mattermost, запитують у цьому чаті &mdash; кнопками, де застосунок їх має, і «відповідь від 1 до 5», де не має &mdash; замість листа. WhatsApp лише поки відкрите його 24-годинне вікно; інакше, а також якщо повідомлення в чаті не вдалося, використовується опитування поштою.',
