    'help' => [
        'case' => [
            'nav' => 'Звіти про випадок',
            'heading' => 'Звіти про випадок',
            'intro' => 'Коли рецензент або аудитор запитує, як було опрацьовано випадок, <strong>Експорт</strong> збирає заявку, її листування та завдання, що виконали роботу, в один документ для друку - тож нікому не доводиться переписувати це вручну.',
            'step1' => '<strong>Відкрийте заявку</strong> і виберіть <strong>Експорт</strong> на її панелі інструментів (у меню <strong>Ще</strong>, якщо панель читання вузька). Звіт відкриється в новій вкладці. Для завдання без заявки скористайтеся кнопкою документа вгорі вікна завдання.',
            'step2' => '<strong>Позначте, що включити</strong>, на панелі ліворуч. Звіт перемальовується під час позначення, і поки ви вибираєте, нічого не записується.',
            'step3' => '<strong>Виберіть макет</strong>: титульну сторінку, сторінку змісту, кожен розділ з нової сторінки та верхній колонтитул із номерами сторінок.',
            'step4' => '<strong>Друк</strong>, а потім виберіть <em>Зберегти як PDF</em> у вікні друку. Зніміть позначку з власних <em>Верхніх і нижніх колонтитулів</em> браузера - звіт друкує свої.',
            'contents' => '<strong>Що входить:</strong> огляд заявки (з її додатковими полями, пов\'язаними активами, конфігураційними одиницями та пов\'язаними заявками); кожне повідомлення, від найстаршого; нотатки; чек-листи заявки; кожне пов\'язане завдання з підзавданнями, результатами чек-листів і примітками про винятки, відповідями на форми, виконаними процедурами, подальшими діями та коментарями; історія заявки та кожного завдання; а також перелік документів і вкладень електронної пошти з відбитком, який FreeITSM записав для кожного документа.',
            'layout' => '<strong>Макет:</strong> сторінка змісту перелічує кожен розділ і завдання, і кожен запис є посиланням у збереженому PDF. Верхній колонтитул і номери сторінок (<em>Сторінка 3 з 12</em>) потребують актуальної версії Chrome або Edge; інші браузери друкують звіт без них.',
            'who' => '<strong>Хто що бачить:</strong> звіт показує лише те, що ви могли бачити на екрані. Завдання, активи, конфігураційні одиниці, пов\'язані заявки, документи та відповіді на форми перевіряються кожне за власним правилом, а все, що вам не можна бачити, <em>підраховується</em> - але ніколи не називається, - щоб читач знав, що дещо пропущено. <strong>Внутрішні нотатки не включаються, доки ви їх не позначите</strong>, адже звіт зазвичай виходить за межі команди.',
            'recorded' => '<strong>Що записується:</strong> друк додає до журналу аудиту заявки рядок <em>Звіт про випадок</em> з указанням, хто друкував і які розділи охоплено. Попередній перегляд і зміна вибору нічого не записують.',
            'note' => 'Звіт про випадок - це копія запису, а не виклад: нічого не переформульовується й не скорочується, зображення всередині листів не відтворюються, файли перелічуються, а не включаються, і з\'являється лише та історія, яку FreeITSM справді записав. Розділ, який неможливо прочитати, повідомляє про це червоним, а не виглядає порожнім.',
        ],
        'workspace' => [
            'nav' => 'Робочий простір і таблиця заявок',
            'heading' => 'Робочий простір і таблиця заявок',
            'intro' => 'Ще два способи опрацьовувати заявки, обидва необов\'язкові. <strong>Робочий простір</strong> розкладає одну заявку так, щоб з нею було зручно працювати, а не лише читати. <strong>Таблиця заявок</strong> показує список заявок у вигляді таблиці, яку можна фільтрувати, сортувати та зберігати.',
            'ws_title' => 'Робочий простір',
            'ws_what' => 'У робочому просторі властивості заявки розташовані в стовпці ліворуч, а її <strong>Листування</strong>, <strong>Робота</strong> (чек-листи, форми та пов\'язані завдання), <strong>Посилання</strong>, <strong>Час і SLA</strong> та <strong>Історія</strong> - це вкладки поруч. Панель інструментів і всі елементи керування ті самі, що й у панелі читання - змінюється лише їх розташування. <strong>Чек-лист</strong> заявки перелічує кожен крок із прапорцем на вкладці «Робота»; <strong>Згорнути</strong> показує лише наступний крок (запам\'ятовується у вашому браузері), а <strong>Відкріпити</strong> усе ще відкриває його в окремому вікні.',
            'ws_admin' => '<strong>Адміністратор вмикає його</strong> у <strong>Заявки &rarr; Налаштування &rarr; Загальні &rarr; Робочий простір заявки</strong>: <em>Вимкнено</em> (за замовчуванням), <em>Лише заявки, перетворені на робочий простір</em> або <em>Кожна заявка</em>.',
            'ws_make' => '<strong>Перетворення заявки на робочий простір:</strong> за середнього налаштування відкрийте заявку та виберіть <strong>Ще &rarr; Зробити робочим простором</strong> (а <strong>Назад до панелі читання</strong> скасовує це). Це стосується самої заявки, тож усі, хто з нею працює, бачать її однаково, а дія записується в історію заявки.',
            'ws_own' => '<strong>Ваш власний вибір:</strong> коли функцію ввімкнено, <strong>Використовувати робочий простір</strong> у меню фільтра списку або в <strong>Система &rarr; Налаштування</strong> вимикає її лише для вас. Заявка, перетворена на робочий простір, тоді показує невелику позначку <em>Робочий простір</em>, щоб ви знали, що колега працює з нею саме так.',
            'ws_checklist' => '<strong>Чек-листи заявки перелічують кожен крок:</strong> на вкладці <strong>Робота</strong> чек-лист показує всі свої кроки з прапорцями. <strong>Згорнути</strong> зменшує його до наступного кроку, як це показує панель читання, а <strong>Розгорнути</strong> повертає решту - ваш браузер запам\'ятовує, що ви вибрали. <strong>Відкріпити</strong> усе ще відкриває повний чек-лист у вікні.',
            'ws_tasks' => '<strong>Пов\'язані завдання відкриваються на місці:</strong> натисніть на завдання на вкладці <strong>Робота</strong>, і там відкриється його власний редактор - разом із чек-листами, формами, процедурами, підзавданнями, коментарями та документами. <strong>Відкрити окремо</strong> відкриває його в окремому вікні, як і раніше; Ctrl-клацання робить те саме. Щоб редагувати завдання, потрібен доступ до Завдань.',
            'ws_safe' => '<strong>Нічого недописаного не губиться:</strong> перехід до іншої заявки або вимкнення робочого простору, коли відповідь, нотатку чи зміну завдання не збережено, спершу запитує вас і чекає на все, що ще зберігається.',
            'tb_title' => 'Таблиця заявок',
            'tb_what' => 'Виберіть <strong>Таблиця</strong> замість <strong>Повідомлення</strong> у рядку дій угорі Заявок (або в <strong>Система &rarr; Налаштування</strong>). Тека, у якій ви перебуваєте, стає фільтром таблиці; добирайте стовпці, фільтруйте й сортуйте їх, шукайте та переходьте списком по 25, 50 або 100 заявок. <strong>Зберегти вигляд</strong> зберігає макет для вас, вашої команди або для всіх.',
            'tb_same' => 'Клацання, Ctrl- і Shift-клацання, клацання правою кнопкою, перетягування до теки та масові дії працюють так само, як у списку повідомлень, а таблиця ніколи не показує заявку, якої не показав би список.',
            'tb_export' => '<strong>Експорт у CSV:</strong> кнопка CSV експортує <em>кожну</em> заявку, що відповідає фільтру, а не лише сторінку, зі стовпцями, які зараз показано. Хто може це робити, задається в <strong>Заявки &rarr; Налаштування &rarr; Загальні &rarr; Хто може експортувати список заявок</strong>: лише адміністратори (за замовчуванням), будь-хто з доступом до Заявок або ніхто. Кнопку не показано тим, кому вона недоступна.',
            'tb_columns' => '<strong>Для кого заявка:</strong> стовпці <strong>Ініціатор</strong> та <strong>Email ініціатора</strong> показують особу, для якої створено заявку, і її адресу електронної пошти. Вони приховані, доки ви не позначите їх у <strong>Стовпцях</strong>; за обома можна сортувати, і обидва потрапляють в експорт CSV, коли їх показано.',
        ],
        'page_title' => 'Service Desk - Посібник із заявок',
        'sidebar_title' => 'Посібник',
        'hero_title' => 'Посібник модуля Заявки',
        'hero_sub' => 'Реєструйте, відстежуйте та вирішуйте запити IT-підтримки з єдиної папки вхідних &mdash; розроблено для команд service desk.',
        'nav' => [
