            'settings' => 'Налаштування',
            'tips' => 'Швидкі поради',
            'companies' => 'Компанії',
        ],
        'overview' => [
            'heading' => 'Огляд',
            'intro' => 'Модуль Заявки є ядром вашого IT service desk. Він надає знайомий інтерфейс у стилі поштового клієнта для управління запитами підтримки, інцидентами та сервісними завданнями. Заявки надходять від кінцевих користувачів електронною поштою або вручну, а аналітики опрацьовують їх за допомогою папок, пріоритетів і таймерів SLA &mdash; усе необхідне для надання оперативної IT-підтримки.',
            'card_inbox_title' => 'Вхідні',
            'card_inbox_body' => 'Вхідні на основі папок, змодельовані на кшталт поштового клієнта. Перегляньте папки «Мої заявки», «Не призначено», «Усі відкриті» та «Закриті». Натисніть будь-яку заявку, щоб відкрити панель читання з повними деталями, історією та діями.',
            'card_dashboard_title' => 'Панель керування',
            'card_dashboard_body' => 'Створіть персоналізовану панель керування з настроюваними віджетами Chart.js. Візуалізуйте обсяги заявок, час відповіді, розподіл за категоріями та навантаження аналітиків за допомогою стовпчастих, кругових, кільцевих і лінійних діаграм.',
            'card_calendar_title' => 'Календар',
            'card_calendar_body' => 'Переглядайте заявки в сітці календаря відповідно до дат їх створення, виконання або вирішення. Швидко виявляйте прострочені елементи та плануйте тиждень, охоплюючи загальну картину заявок.',
            'card_rota_title' => 'Графік чергувань',
            'card_rota_body' => 'Плануйте зміни аналітиків і графіки чергування. Дізнавайтеся, хто доступний у будь-який момент, плануйте покриття на вихідні та свята й переконуйтеся, що жодна заявка не залишиться без уваги.',
        ],
        'inbox' => [
            'heading' => 'Вхідні',
            'intro' => 'Вхідні є основним робочим простором для аналітиків. Вони використовують розмітку з трьох панелей &mdash; папки ліворуч, список заявок по центру та панель читання праворуч &mdash; тож ви можете сортувати й відповідати, не покидаючи сторінки.',
            'p_live' => '<strong>Вона оновлюється сама.</strong> Щохвилини вхідні перевіряють ваші поштові скриньки та шукають нове в заявках, які ви можете бачити &mdash; лист, зібраний у фоні, повідомлення з WhatsApp, Telegram, Slack, Teams чи Mattermost, відповідь колеги &mdash; і коли щось надійшло, список і лічильники тек оновлюються самі, так само як після натискання кнопки оновлення. Заявка, яку ви читаєте, і відповідь, яку друкуєте, залишаються недоторканими.',
            'p_folders' => 'Панель папок організовує заявки на логічні групи. Кожна папка відображає кількість непрочитаних, щоб ви одразу помічали нову роботу:',
            'field_my' => '<strong>Мої заявки</strong> &mdash; заявки, призначені вам. Це ваша особиста черга й найкраще місце для початку кожного дня.',
            'field_unassigned' => '<strong>Не призначено</strong> &mdash; заявки, які надійшли, але ще не мають аналітика. Беріть тут елементи, щоб прийняти їх.',
            'field_all_open' => '<strong>Усі відкриті</strong> &mdash; кожна заявка, яку ще не закрито, незалежно від того, хто є її власником. Корисно для менеджерів і тімлідів, що відстежують загальний обсяг.',
            'field_closed' => '<strong>Закриті</strong> &mdash; вирішені заявки. Шукайте тут, коли потрібно знайти минуле рішення або повторно відкрити проблему.',
            'field_dept' => '<strong>Папки відділів</strong> &mdash; заявки, згруповані за відділом (наприклад, IT, HR, Фінанси). Відділи налаштовуються в Налаштуваннях і автоматично з\'являються як підпапки.',
            'switch_heading' => '<strong>Перемикання між групуванням за відділом і за аналітиком</strong>',
            'switch_body' => 'Невелика кнопка-перемикач з двох кнопок у верхній частині панелі папок переключається між двома поданнями одних і тих самих даних. Групування за <strong>відділом</strong> (типово) виводить заявки під кожним відділом із підпапками за статусом усередині; групування за <strong>аналітиком</strong> перевертає структуру так, що кожна папка верхнього рівня представляє особисту чергу аналітика з підпапками за статусом усередині. Папка <strong>Не призначено</strong> є контекстно-залежною в кожному поданні &mdash; у поданні за відділом вона містить заявки без призначеного відділу; у поданні за аналітиком &mdash; заявки без призначеного виконавця &mdash; тож ви завжди бачите, що потребує опрацювання. Ваш вибір зберігається для кожного аналітика, щоб кожен член команди зберігав зручне для нього подання між сесіями.',
            'p_actions' => 'Над списком заявок розташовано чотири кнопки дій: <strong>Нова</strong> — створити заявку, <strong>Пошук</strong> — знайти заявки за ключовим словом, номером або ініціатором, <strong>Фільтр</strong> — звузити те, що ви бачите, і <strong>Оновити</strong> — перезавантажити поточну теку.',
            'filter_body' => 'Кнопка <strong>Фільтр</strong> (воронка) звужує теки та список разом, як би вони не були згруповані. <strong>Мої</strong> показує лише заявки, призначені вам, а <strong>Сховати закриті</strong> прибирає всі заявки, чий статус позначено як закритий. Поки фільтр увімкнено, на воронці є крапка, а біля назви списку з\'являється мітка, тож ви завжди знаєте, що бачите не все. Коли теки згруповано за <strong>Аналітиком</strong>, ваша власна тека замість цього лежить угорі як <strong>Мої заявки</strong>. У пошуку є власний перемикач <strong>Включати закриті заявки</strong>, за замовчуванням увімкнений, бо пошук зазвичай спрямований на стару заявку. Обидва вибори зберігаються лише для вас.',
            'row_name' => 'Кожен рядок показує номер заявки, а потім ім\'я. За замовчуванням це <strong>особа, яка створила заявку</strong>, і воно залишається незмінним протягом усього життя заявки. Якщо ви натомість хочете бачити того, хто надіслав останнє повідомлення &mdash; це стає вашою власною поштовою скринькою, щойно ви відповіли &mdash; змініть <strong>Ім\'я біля номера заявки</strong> в розділі <strong>Налаштування &rarr; Відображення рядків</strong>, де також можна сховати ім\'я і залишити лише номер. Ця вкладка — ваше особисте налаштування: вона нічого не змінює для інших.',
            'tip' => 'Натисніть будь-яку заявку в списку, щоб завантажити її в панелі читання. Звідти ви можете оновлювати поля, додавати коментарі, відповідати електронною поштою або прикріплювати файли &mdash; усе без переходу зі вхідних.',
        ],
        'live' => [
            'heading' => 'Живі оновлення',
            'body' => 'FreeITSM підтримує ваш екран у згоді з усіма іншими. Коли колега змінює заявку - її статус, пріоритет, відповідального чи команду, відповідь, нотатку - ваш список заявок і відкрита заявка оновлюються приблизно за 15 секунд без натискання «Оновити». Дошка завдань, відкрите завдання та дзвіночок працюють так само.',
            'what' => 'Перевірка виконується лише поки вкладка перед вами, а щойно ви повертаєтеся до неї, усе наздоганяється. Зміна, яку ви робите в одній вкладці, одразу показується в інших ваших вкладках.',
            'safe' => 'Вона ніколи не знищує те, що ви робите. Поки ви пишете відповідь чи нотатку, вводите текст у полі або маєте відкрите меню, нові повідомлення все одно з\'являються в листуванні, а решта чекає за невеликим запитом <strong>Щойно оновлено кимось іншим &middot; Оновити</strong>.',
            'setting' => '<strong>Налаштування &rarr; Живі оновлення</strong> дозволяє вибрати кожні 15 секунд (за замовчуванням), 30 секунд, щохвилини або вимкнути.',
        ],
        'watch' => [
            'heading' => 'Стеження за заявкою',
            'body' => 'Стежте за заявкою, не будучи її власником - керівник команди, який дивиться за великим інцидентом, або аналітик, що передав її далі. Стежачі отримують повідомлення про заявку так, ніби вона їхня, відповідно до власних налаштувань сповіщень.',
            'how' => '<strong>Стежити</strong> на панелі інструментів заявки або клацніть на ній правою кнопкою у списку й виберіть <strong>Стежити</strong>. Клацніть правою кнопкою на виділених заявках, щоб стежити за всіма. На заявці, за якою ви вже стежите, кнопка на панелі інструментів і контекстне меню натомість показують <strong>Припинити стежити</strong> - за виділеними можна почати стежити, але не можна припинити одним кроком.',
            'others' => 'Кнопка <strong>Стежити</strong> показує, хто стежить. Маючи доступ на запис до Заявок, ви можете <strong>додати колегу</strong> або прибрати когось; кожен може прибрати себе.',
            'what' => '<strong>Заявки &rarr; Налаштування &rarr; Загальні &rarr; Стеження за заявками</strong> визначає, про що чують стежачі - відповіді, нотатки, статус, пріоритет, перепризначення, попередження SLA та порушення - про все, якщо адміністратор не зніме позначку з окремих пунктів. Перепризначення доходить до стежачого як «перепризначено», ніколи як «призначено вам», і має власний перемикач у налаштуваннях кожної особи.',
            'leaver' => 'Деактивований аналітик ніколи не отримує повідомлень про заявку, за якою стежить. <strong>Заявки &rarr; Налаштування &rarr; Загальні &rarr; Коли стежачого деактивовано</strong> визначає, що станеться з його стеженням: <strong>Зупинити</strong> (за замовчуванням) ховає його з поля зору й повертає, якщо аналітика знову зроблять активним; <strong>Вилучити</strong> прибирає аналітика з усіх заявок, за якими він стежить, коли його деактивують.',
            'note' => 'Стежити за заявкою можуть лише ті, хто може її бачити, і якщо вони перестають її бачити, то перестають і отримувати повідомлення. Нікого не повідомляють про його власну зміну. Об\'єднання переносить стежачих на заявку, що залишається.',
        ],
        'forms_on_ticket' => [
            'heading' => 'Форми на заявці',
            'body' => 'Прикріпіть форму з модуля «Форми» до заявки та заповніть її там - запит на нового працівника, якому потрібна форма обладнання, або інцидент безпеки, якому потрібен звіт. Відповіді зберігаються разом із заявкою.',
            'switch' => '<strong>Заявки &rarr; Налаштування &rarr; Чек-листи &rarr; Форми на заявках</strong> вмикає це (доки ви не ввімкнете, вимкнено, і модуль «Форми» також має бути ввімкнено). Тоді на панелі інструментів кожної заявки з\'являється кнопка <strong>Форми</strong> з лічильником надісланих. У робочому просторі форми також з\'являються на вкладці <strong>Робота</strong>. Клацніть правою кнопкою на заявці або виділенні та виберіть <strong>Додати форму</strong>, щоб додати форму, не відкриваючи заявку.',
            'how' => '<strong>Форми</strong> відкриває список: <strong>Додати</strong> вибирає форму (завжди її найновішу версію), <strong>Заповнити</strong> відкриває її у вікні, <strong>Зберегти чернетку</strong> зберігає незавершені відповіді, які колеги можуть продовжити, а <strong>Виправити</strong> замінює надіслану відповідь, залишаючи стару у «Формах».',
            'required' => 'Кожна форма є <strong>Обов\'язковою - блокує закриття</strong>, <strong>Обов\'язковою - попереджає під час закриття</strong> або <strong>Необов\'язковою</strong>. Форму, що блокує, треба надіслати, перш ніж заявка зможе набути закритого статусу; форма з попередженням запитує та записує, хто все одно її закрив.',
            'note' => 'Щоб заповнити форму, потрібен доступ на запис до Форм і до Заявок. Щоб читати відповіді, потрібен доступ до Форм або дозвіл <strong>Читати відповіді на форми в заявках, які ви бачите</strong> (налаштування ролі); решта бачать, хто надіслав форму і коли, але не що було написано. Відповідь, на яку спирається заявка, не можна видалити з Форм. Відповіді з\'являються у звіті про випадок заявки та в REST API.',
        ],
        'faster' => [
            'heading' => 'Швидша робота',
            'intro' => 'Чотири речі, які перетворюють напружений ранок на керований: збережені відповіді, дії з багатьма заявками одночасно та розміщення розмов там, де їм належить бути.',
            'templates_heading' => 'Готові відповіді',
            'templates_body' => 'Ви постійно надсилаєте одні й ті самі відповіді. Напишіть одну раз, потім натисніть <strong>Шаблони</strong> внизу ліворуч у вікні відповіді, щоб вставити її в місце курсора &mdash; вона додається до вже набраного, а не замінює його. Шаблони є форматованим текстом і підтримують ті самі заповнювачі <code>[merge_code]</code>, що й автоматичні листи, тож <code>[requester_first_name]</code> стає справжнім ім\'ям під час вставки.',
            'templates_team' => '<strong>Командні шаблони</strong> &mdash; спільні для всіх, налаштовуються в Налаштування &rarr; Шаблони відповідей.',
            'templates_mine' => '<strong>Власні</strong> &mdash; збережіть чернетку через <em>Зберегти чернетку як шаблон</em>. Приватні лише для вас, особливий дозвіл не потрібен.',
            'templates_tip' => 'Називайте шаблон за ситуацією («Принтер не працює &mdash; перші кроки»), а не за формулюванням. Саме це ви шукатимете очима о 9 ранку.',
            'select_heading' => 'Вибір кількох заявок',
            'select_body' => 'Список заявок працює як в Outlook чи Провіднику. Без прапорців.',
            'key_click' => 'Клацання',
            'key_click_d' => 'вибрати одну заявку та відкрити її',
            'key_ctrl' => 'Ctrl+клацання',
            'key_ctrl_d' => 'додати або прибрати одну, не чіпаючи решту',
            'key_shift' => 'Shift+клацання',
            'key_shift_d' => 'вибрати весь блок від місця останнього клацання',
            'key_kb' => 'Клавіатура',
            'key_kb_d' => 'стрілки для переміщення, Shift+стрілки для розширення вибору, Ctrl+стрілки та пробіл для вибору розкиданих заявок, Ctrl+A для всього, Escape для скасування вибору',
            'select_actions' => 'Коли вибрано кілька заявок, <strong>клацніть правою кнопкою на будь-якій з них</strong>, щоб встановити статус, пріоритет, відділ, тип або виконавця одразу для всіх &mdash; або перетягніть увесь набір у теку. Що показує екран, поки вибрано кілька заявок, — це ваш вибір, у меню облікового запису в розділі Налаштування.',
            'select_tip' => 'Клацання правою кнопкою на заявці, яка <em>не</em> входить до вашого вибору, скасовує вибір і націлюється лише на неї. Це зроблено навмисно &mdash; ви ніколи не зможете виконати дію над набором, про який уже думали, що з ним покінчено.',
            'merge_heading' => 'Об\'єднання дублікатів',
            'merge_body' => 'Двоє людей повідомили про той самий збій? Виберіть заявки, клацніть правою кнопкою, <strong>Об\'єднати</strong>. Розмови об\'єднуються, і якщо у вас налаштовано провайдера AI, FreeITSM пише короткий брифінг про те, що всі запитували і що вже зроблено, тож той, хто візьметься за заявку, не мусить читати чотири гілки листування.',
            'merge_tip' => 'Нічого ніколи не видаляється. Заявка, яку об\'єднали, зберігає свій номер, залишається доступною для пошуку, показує, куди вона перейшла &mdash; і клієнт, який відповідає на старий лист про неї, все одно доходить до вас.',
            'split_heading' => 'Розділення заявки',
            'split_body' => 'Протилежна дія. Коли хтось піднімає другу, не пов\'язану тему посеред розмови, натисніть <strong>Розділити</strong> на цьому повідомленні (або клацніть правою кнопкою на заголовку повідомлення). Воно переміщується в нову заявку, за бажанням разом із усіма новішими повідомленнями, а оригінал зберігає позначку, що показує, куди вони перейшли.',
            'split_tip' => 'Дайте новій заявці належну тему. За замовчуванням використовується тема перенесеного повідомлення, яка зазвичай є «RE:» для <em>старої</em> проблеми.',
            'undo_heading' => 'Передумали',
            'undo_body' => 'Обидві дії можна скасувати з банера на заявці. Скасування <strong>розділення</strong> відхиляється, щойно хтось відповів у новій заявці, додав нотатку або зафіксував час &mdash; вам точно повідомляють, що саме заважає. Скасування <strong>об\'єднання</strong> повертає заявці її повідомлення, нотатки й зафіксований час та відкриває її знову точно такою, якою вона була, але відповіді, написані в іншій заявці після об\'єднання, залишаються там.',
        ],
        'working' => [
            'heading' => 'Робота із заявками',
            'intro' => 'Кожен запит підтримки проходить певний життєвий цикл: створюється, сортується, опрацьовується і врешті-решт вирішується. Модуль Заявки надає інструменти для ефективного управління кожним етапом — від первинної реєстрації до закриття.',
            'creating_heading' => '<strong>Створення нової заявки</strong>',
            'step1' => '<strong>Натисніть «Нова»</strong> &mdash; відкрийте модальне вікно нової заявки з панелі інструментів вхідних. Введіть ім\'я та адресу електронної пошти заявника, щоб він міг отримувати оновлення.',
            'step2' => '<strong>Вкажіть тему</strong> &mdash; напишіть чіткий, стислий опис проблеми. Він відображається в списку заявок і в будь-яких повідомленнях електронної пошти, надісланих кінцевому користувачеві.',
            'step3' => '<strong>Оберіть відділ, тип і пріоритет</strong> &mdash; виберіть відповідний відділ, тип заявки (наприклад, Інцидент, Сервісний запит) і рівень пріоритету. Ці поля керують таймерами SLA і правилами маршрутизації.',
            'step4' => '<strong>Додайте опис</strong> &mdash; надайте повні деталі проблеми за допомогою редактора форматованого тексту. Включіть кроки для відтворення, повідомлення про помилки та будь-який важливий контекст, який знадобиться аналітику для вирішення.',
            'step5' => '<strong>Зберегти</strong> &mdash; заявку створено з унікальним номером, і вона з\'являється у відповідній папці. Годинник SLA запускається негайно відповідно до пріоритету.',
            'editing_heading' => '<strong>Редагування заявок та управління ними</strong>',
            'editing_body' => 'Після створення заявки ви можете оновити будь-яке поле з панелі читання. Ключові поля:',
            'card_status_title' => 'Статус',
            'card_status_body' => 'Відстежуйте життєвий цикл заявки: Нова, Відкрита, В роботі, В очікуванні, Вирішена, Закрита',
            'card_priority_title' => 'Пріоритет',
            'card_priority_body' => 'Установіть терміновість і вплив: Критичний, Високий, Середній, Низький. Кожен рівень має власний цільовий показник SLA',
            'card_category_title' => 'Категорія',
            'card_category_body' => 'Класифікуйте тип проблеми: Апаратне забезпечення, Програмне забезпечення, Мережа, Доступ, Загальне. Корисно для звітності',
            'card_analyst_title' => 'Призначений аналітик',
            'card_analyst_body' => 'Особа, відповідальна за вирішення заявки. Перепризначення фіксується в журналі активності',
            'card_enduser_title' => 'Кінцевий користувач',
            'card_enduser_body' => 'Особа, яка надіслала запит. Пошук за ім\'ям або електронною поштою для прив\'язки до наявного запису користувача',
            'card_dept_title' => 'Відділ',
            'card_dept_body' => 'Маршрутизуйте заявки до відповідної команди. Відділи визначають групування папок і фільтри панелі керування',
            'flow_new' => 'Нова',
            'flow_in_progress' => 'В роботі',
            'flow_resolved' => 'Вирішено',
            'flow_closed' => 'Закрито',
            'triage_heading' => '<strong>Сортування перетягуванням</strong>',
            'triage_body' => 'Не обов\'язково відкривати заявку, щоб відсортувати її. Перетягніть будь-який рядок зі списку заявок на папку, щоб оновити поля одним рухом:',
            'triage_dept' => '<strong>Подання за відділом</strong> &mdash; перетягніть на папку відділу для перепризначення, перетягніть на підпапку статусу під відділом, щоб оновити обидва поля одночасно, перетягніть на <strong>Не призначено</strong>, щоб очистити відділ.',
            'triage_analyst' => '<strong>Подання за аналітиком</strong> &mdash; перетягніть на папку аналітика, щоб призначити його власником (встановлює як <code>assigned_analyst_id</code>, так і <code>owner_id</code>, щоб поле «Власник» у панелі читання залишалося синхронізованим), перетягніть на підпапку статусу, щоб оновити обидва, перетягніть на <strong>Не призначено</strong>, щоб зняти призначення.',
            'triage_spring' => '<strong>Розгортання папок при наведенні</strong> &mdash; наведіть курсор на згорнуту папку під час перетягування, і вона автоматично розгорнеться (у стилі Outlook), щоб будь-який вкладений статус можна було досягти без попереднього скидання.',
            'fullscreen_heading' => '<strong>Повноекранний режим</strong>',
            'fullscreen_body' => 'Коли вам потрібно зосередитися на одній заявці &mdash; довга переписка, складна зміна, складання детальної відповіді &mdash; перейдіть у повноекранний режим. Список папок і список заявок зникають, розмова займає всю доступну ширину, а властивості (Відділ, Тип, Статус, Джерело, Вирішено з першого разу, IT-навчання, Власник) переміщуються до вертикальної бічної панелі праворуч.',
            'fullscreen_max' => '<strong>Значок розгортання</strong> &mdash; невелика піктограма в правому кінці рядка теми заявки. Натисніть, щоб увійти в повноекранний режим; натисніть знову, щоб повернутися до макету з 3 панелями.',
            'fullscreen_dbl' => '<strong>Подвійне клацання по рядку</strong> &mdash; двічі клацніть будь-яку заявку в списку, щоб відкрити її одразу в повноекранному режимі, жест у стилі Outlook «справді відкрити цю».',
            'fullscreen_sticks' => '<strong>Зберігається між виборами</strong> &mdash; перебуваючи в повноекранному режимі, перехід до наступної заявки зберігає вас у ньому. Нове завантаження сторінки (F5) без вибраної заявки повертає до стандартного 3-колонкового макету, тому ви не можете опинитися в пастці з прихованим списком папок.',
            'fullscreen_back' => '<strong>Назад</strong> &mdash; панель над заявкою показує її номер і кнопку <strong>Назад</strong>, яка повертає вас просто до списку саме таким, яким ви його залишили, з клавіатурою знову на списку - тож стрілки переходять між заявками, а Enter одразу відкриває наступну. <strong>Escape</strong> робить те саме, щойно закриється будь-яке вікно чи меню, відкрите над заявкою. Жодне з них не вимикає повноекранний режим: наступна заявка все одно відкриється на весь екран (перемикач - значок стискання), а повернувшись до заявки, яку ви залишили, ви знайдете там розпочату відповідь.',
            'fullscreen_keys' => '<strong>Клавіші прокручують заявку</strong> &mdash; у повноекранному режимі стрілки, Page Up / Page Down і пробіл прокручують листування, а не прихований список заявок. У вікні зображення чи PDF вони прокручують це вікно. У звичайному трипанельному вигляді клацніть на заявці, і клавіші прокручують і її; клацніть на списку, щоб повернутися до переходу між заявками.',
            'viewer_heading' => '<strong>Зображення та PDF відкриваються над заявкою</strong>',
            'viewer_body' => 'Клацніть на зображенні чи PDF, доданому до нотатки, або на тому, що є у списку <strong>Вкладень</strong> заявки (його мініатюра чи рядок), і воно відкриється у вікні поверх заявки &mdash; у тому самому засобі перегляду, що й у модулі «Файли». Заявка лишається точно там, де була.',
            'viewer_window' => '<strong>Пересувайте та змінюйте розмір</strong> &mdash; перетягніть заголовок, щоб пересунути вікно, і будь-який край чи кут, щоб змінити розмір; двічі клацніть на заголовку або перетягніть його до верху екрана, щоб розгорнути на весь екран. Зображення чи PDF підлаштовується під розмір вікна, доки ви самі не збільшите чи не зменшите масштаб &mdash; <strong>Вмістити</strong> повертає це назад. Відкривайте кілька, і вони розташуються поруч.',
            'viewer_close' => '<strong>Закрити</strong> &mdash; &times; у заголовку або <strong>Escape</strong> (закриває вікно, що попереду). <strong>Завантажити</strong> зберігає файл. На телефоні файл відкривається на весь екран із кнопкою «Назад».',
            'viewer_other' => '<strong>Інші файли</strong> &mdash; документи Word, електронні таблиці та все інше, як і раніше, завантажуються або відкриваються в новій вкладці. Щоб відкрити зображення чи PDF нотатки в новій вкладці, клацніть на ньому, утримуючи Ctrl.',
            'paste_heading' => '<strong>Вставте знімок екрана в нотатку</strong>',
            'paste_body' => 'Скопіюйте знімок екрана, клацніть у полі <strong>Додати нотатку</strong> і натисніть <strong>Ctrl+V</strong>. Зображення потрапляє туди, де курсор, із вашим текстом до та після нього, і лишається на цьому місці після збереження нотатки. Клацніть на ньому, щоб відкрити в засобі перегляду. <strong>Backspace</strong> прибирає його до збереження.',
            'paste_shared' => '<strong>Спільні нотатки ділять свої зображення</strong> &mdash; ініціатор бачить їх у порталі, на місці. У внутрішній нотатці вони такі ж приватні, як і сама нотатка.',
            'paste_save' => '<strong>Нічого не зберігається, доки ви не натиснете «Зберегти»</strong> &mdash; закрийте поле, і зображення зникнуть разом із ним. Якщо зображення відхилено, нотатку також не збережено, причину показано, а ваш текст лишається в полі.',
            'paste_text' => '<strong>Текст лишається текстом</strong> &mdash; вставлення з Word, вебсторінки чи Excel переносить слова без їхнього форматування. Кнопка <strong>Прикріпити</strong> усе ще працює для будь-якого іншого файлу.',
            'rightclick_heading' => '<strong>Контекстне меню для швидких дій</strong>',
            'rightclick_body' => 'Клацніть правою кнопкою миші будь-яку заявку в списку, щоб відкрити контекстне меню. У меню вгорі відображається номер заявки, щоб ви знали, з чим працюєте, і кожна дія стосується заявки, на якій клацнули, <em>не змінюючи</em> того, що зараз відкрито в панелі читання &mdash; зручно, коли ви читаєте заявку A і потрібно відсортувати заявку B, не втрачаючи своє місце.',
            'rightclick_status' => '<strong>Установити статус &rarr;</strong> &mdash; спливаюче підменю з переліком усіх активних статусів із кольоровим зразком. Галочка з\'являється поруч із поточним значенням, якщо ви клацаєте правою кнопкою заявку, яку відкрили. Вибір негайно оновлює заявку, записує запис у журналі аудиту, оновлює лічильники папок і синхронізує випадний список «Статус» у панелі читання, якщо це застосовно.',
            'rightclick_priority' => '<strong>Установити пріоритет &rarr;</strong> &mdash; такий самий патерн підменю, що формується з активних пріоритетів довідника з кольоровим зразком кожного. Перший рядок є варіантом <em>(без пріоритету)</em> для очищення призначення (пріоритет може бути порожнім).',
            'rightclick_assign' => '<strong>Призначити &rarr;</strong> &mdash; підменю з переліком усіх завантажених аналітиків із сірим чіпом ініціалів, плюс рядок <em>(не призначено)</em> вгорі для очищення. Вибір встановлює як <code>assigned_analyst_id</code>, так і <code>owner_id</code>, щоб поле «Власник» у панелі читання залишалося синхронізованим.',
            'rightclick_cmdb' => '<strong>Прив\'язати об\'єкт CMDB&hellip;</strong> &mdash; відкриває пошук з підказками. Натисніть результат, щоб прив\'язати його, потім продовжуйте вибір &mdash; поле введення очищується і повертає фокус для наступного вибору, а журнал «Нещодавно прив\'язані» всередині модального вікна показує поточний список підтверджень із зеленими галочками.',
            'rightclick_time' => '<strong>Зафіксувати час&hellip;</strong> &mdash; відкриває модальне вікно з полем хвилин і вибором дати/часу (типово «зараз», тому можна також вказати ретроспективну дату) і необов\'язковим полем нотаток.',
            'rightclick_more' => '<strong>Прикріпити чек-лист &rarr;</strong>, <strong>Додати форму &rarr;</strong> і <strong>Стежити</strong> - прикріпити чек-лист (спершу найкращі збіги), додати форму або стежити за заявкою, не відкриваючи її. На виділеному вони діють на кожну вибрану заявку, пропускаючи ті, що вже мають цей чек-лист або форму.',
            'rightclick_phone' => '<strong>На телефоні</strong> натисніть і потримайте заявку пів секунди, щоб відкрити те саме меню як панель на весь екран. Вибір із додатковими параметрами &mdash; Встановити статус, Встановити пріоритет, Призначити &mdash; зсувається до них, а <strong>Назад</strong> повертає назад.',
            'rightclick_tip' => 'Якщо заявка, з якою ви працюєте через контекстне меню, є тією самою, що відкрита в панелі читання, відповідний розділ там (випадні списки «Статус» / «Пріоритет», об\'єкти CMDB, записи часу) автоматично оновлюється після закриття модального вікна, щоб UI залишався синхронізованим.',
            'time_heading' => '<strong>Фіксація часу</strong>',
            'time_body' => 'Витрачений на заявку час фіксується у спеціальному розділі <strong>Записи часу</strong> в панелі читання, розміщеному між панеллю пов\'язаних об\'єктів CMDB і панеллю нотаток. У заголовку відображається загальна сума (наприклад, «Загалом 2год 30хв»), а кожен запис нижче показує витрачений час, аналітика, дату та будь-які додані нотатки.',
            'time_step1' => '<strong>Вбудована форма</strong> &mdash; введіть кількість хвилин у числове поле, необов\'язковий короткий опис у поле нотаток і натисніть <strong>Додати</strong>. Новий запис з\'являється одразу вгорі списку з вашим ім\'ям і поточною міткою часу.',
            'time_step2' => '<strong>Ретроспективна дата через контекстне меню</strong> &mdash; якщо потрібно зафіксувати час, який ви забули записати раніше, клацніть правою кнопкою заявку в списку і виберіть <strong>Зафіксувати час&hellip;</strong>. Модальне вікно містить вибір дати/часу, тому ви можете вказати фактичний час виконання роботи.',
            'time_step3' => '<strong>Видалення власних записів</strong> &mdash; поруч із записами, які ви внесли, з\'являється кнопка &times;. Натисніть її (і підтвердьте), щоб здійснити м\'яке видалення &mdash; рядок залишається в базі даних зі значенням <code>is_active = 0</code> для аудиту, але зникає зі списку. Видаляти записи інших аналітиків неможливо.',
            'time_tip1' => 'Час зберігається у вигляді простих хвилин (45 хв, 90 хв тощо) і відображається як <code>45хв</code> або <code>1год 30хв</code> в UI &mdash; достатньо деталізовано для коротких виправлень, без болю від округлення до десятих частин години.',
            'time_tip2' => 'Кожна зміна поля фіксується в журналі активності заявки. Ви завжди можете побачити, хто, що і коли змінив, що є обов\'язковим для відповідності вимогам аудиту та передачі справ між аналітиками.',
        ],
        'comments' => [
            'heading' => 'Коментарі &amp; вкладення',
            'intro' => 'Журнал активності є серцем кожної заявки. Він фіксує кожну виконану дію &mdash; коментарі, зміни полів, надіслані листи та прикріплені файли &mdash; у хронологічній часовій шкалі, що розповідає повну історію запиту підтримки.',
            'adding_heading' => '<strong>Додавання коментарів</strong>',
            'step1' => '<strong>Відкрийте заявку</strong> &mdash; натисніть будь-яку заявку у вхідних, щоб завантажити її панель читання. Прокрутіть вниз, щоб побачити повний журнал активності та поле коментаря внизу.',
            'step2' => '<strong>Напишіть нотатку</strong> &mdash; скористайтеся кнопкою «Додати нотатку», щоб відкрити редактор коментарів. Нотатки є внутрішніми за замовчуванням і видимі лише аналітикам служби підтримки.',
            'step3' => '<strong>Відповідь або переадресація електронною поштою</strong> &mdash; скористайтеся діями «Відповісти» або «Переслати», щоб надіслати повідомлення кінцевому користувачеві або третій стороні. Лист фіксується в журналі активності разом із вмістом вихідного повідомлення.',
            'files_heading' => '<strong>Вкладення файлів</strong>',
            'files_body' => 'Прикріплюйте знімки екрана, журнали, документи або будь-який підтримуючий файл безпосередньо до заявки. Файли можна перетягнути в зону прикріплення або вибрати через файловий браузер. Вкладення зберігаються на сервері й прив\'язуються до журналу активності заявки, тому нічого не губиться.',
            'audit_heading' => '<strong>Журналювання аудиту</strong>',
            'export_heading' => '<strong>Звіти про випадок</strong>',
            'export_body' => 'Для рецензії чи аудитора <strong>Експорт</strong> на панелі інструментів заявки перетворює заявку та її завдання на один звіт для друку - див. <a href="#case-reports">Звіти про випадок</a>.',
            'audit_body' => 'Журнал активності автоматично фіксує кожну дію без участі аналітика. Коли пріоритет змінюється з «Середнього» на «Високий», старе і нове значення записуються. Коли заявку перепризначають, фіксуються як попередній, так і новий аналітик. Це створює повну, захищену від підробки історію, що відповідає вимогам аудиту ITIL і допомагає менеджерам зрозуміти, як опрацьовуються заявки.',
            'tip' => 'Відповідаючи електронною поштою, ви можете додати одержувачів у копію та прикріпити файли в тій самій дії. Вся переписка електронною поштою відображається в потоці журналу активності заявки, зберігаючи всі комунікації в одному місці.',
        ],
        'ai' => [
            'heading' => 'Інструменти AI',
            'intro' => 'Два функції на базі Claude вбудовані в робочий процес заявок: <strong>Покращення відповіді</strong> переписує чорновик у правильно відформатований лист, а <strong>Запит до AI</strong> здійснює пошук у базі знань природною мовою, використовуючи контекст заявки.',
            'cleanup_heading' => '<strong>Покращення відповіді &mdash; кнопка ✨ в редакторі відповідей</strong>',
            'cleanup_body' => 'Введіть швидкий чорновик у відповідь (або просто тезами, наприклад *«потрібно перезапустити службу друку, зробити для них скріншот»*) і натисніть кнопку <strong>✨ Покращити</strong>. Claude переписує текст у правильно відформатований лист &mdash; додає привітання <em>Шановний(-а) [ім\'я],</em> від заявника, виправляє граматику, застосовує налаштований тон і завершує словами <em>З повагою,</em>. Запит заблокований, тому він НЕ вигадуватиме технічні деталі, не вигадуватиме вибачень і не доповнюватиме зміст понад те, що ви написали.',
            'cleanup_streams' => '<strong>Виводиться потоково</strong> &mdash; переписаний текст з\'являється в редакторі по мірі того, як Claude його генерує (без очікування перед спінером).',
            'cleanup_undo' => '<strong>Посилання «Скасувати» на 30с</strong> &mdash; якщо Claude зіпсує переписаний текст, невелике посилання <em>Скасувати</em> з\'являється під редактором протягом 30 секунд після завершення переписування, відновлюючи оригінальний чорновик.',
            'cleanup_tone' => '<strong>За тоном</strong> &mdash; три пресети тону, що налаштовуються в <strong>Налаштуваннях &rarr; Покращення відповіді</strong>: <em>Дружній</em> (типово), <em>Офіційний</em>, <em>Стислий</em>. Вибирайте той, що відповідає стилю вашої команди.',
            'cleanup_key' => '<strong>Власний API-ключ</strong> &mdash; окремий ключ Anthropic від AI-функцій RFP / Бази знань / Workflow, щоб його використання відображалося як окремий рядок на панелі виставлення рахунків Anthropic. Налаштовується в <strong>Налаштуваннях &rarr; Покращення відповіді</strong>.',
            'cleanup_tip' => 'Покращення найкраще підходить для типових відповідей у стилі «я спробував це, будь ласка, спробуйте X». Для довгих, нюансових повідомлень краще писати їх самостійно &mdash; AI чудово справляється зі структурою, але не знає вашого конкретного середовища.',
            'ask_heading' => '<strong>Запит до AI &mdash; кнопка 🤖 на панелі інструментів заявки</strong>',
            'ask_body' => 'Натисніть кнопку <strong>Запит до AI</strong> (🤖) на панелі інструментів заявки, щоб відкрити панель чату, яка знає тему, тіло та контекст панелі читання відкритої заявки. Задавайте питання на кшталт *«чи виникало таке раніше?»* або *«яке звичайне виправлення цієї помилки?»* — вона шукає в <a href="../knowledge/" style="color:#0078d4;">базі знань</a> семантично (через Claude + вбудовування OpenAI) і відповідає з відповідними статтями та прямими посиланнями для їх відкриття.',
            'ask_context' => '<strong>Контекстно-залежна</strong> &mdash; панель знає, яку заявку ви переглядаєте, тому ви можете ставити загальні запитання, а вона сама визначає відповідний контекст.',
            'ask_linked' => '<strong>Пов\'язані статті</strong> &mdash; пропозиції є клікабельними і відкривають відповідну статтю бази знань у новій вкладці.',
            'ask_shared' => '<strong>Спільна з модулем Бази знань</strong> &mdash; AI використовує той самий ключ і модель, що й AI-пошук у Базі знань, тому одноразове налаштування надає обидва варіанти. Деталі налаштування дивіться в довідці модуля Бази знань.',
        ],
        'csat' => [
            'heading' => 'Опитування про задоволеність клієнтів (CSAT)',
            'intro' => 'Надсилайте заявнику опитування задоволеності від 1 до 5 електронною поштою після вирішення заявки, збирайте відповідь на цільовій сторінці без входу та відстежуйте тенденції за аналітиками на спеціальній сторінці аналітики.',
            'modes_heading' => '<strong>Два режими запуску &mdash; оберіть один</strong>',
            'mode_auto' => '<strong>Автоматично при закритті</strong> &mdash; опитування ставиться в чергу автоматично, коли заявка переходить у будь-який закритий статус. Аналітику нічого не потрібно робити &mdash; вирішення запускає опитування.',
            'mode_manual' => '<strong>Лише вручну</strong> &mdash; аналітик натискає кнопку ⭐ <strong>Відгук</strong> на панелі інструментів заявки, коли хоче запитати. Корисно, якщо ви бажаєте вирішувати для кожної заявки окремо, чи запрошувати відгук.',
            'switch_note' => 'Не користуєтеся CSAT взагалі? Вимкніть його в розділі <strong>Система &rarr; Модулі &rarr; Доступність &rarr; Функції заявок</strong>, і він зникне: жодних опитувань, сторінки CSAT, кнопки «Запросити відгук», а старі посилання на опитування повідомлятимуть, що відгуки більше не збираються. Нічого не видаляється.',
            'mode_off' => '<strong>Вимкнено</strong> &mdash; функція вимкнена; листи з опитуваннями не надсилаються.',
            'modes_choose' => 'Вибирайте в <strong>Заявки &rarr; Налаштування &rarr; CSAT</strong>. Ручна кнопка все одно працює в режимі <em>авто</em> &mdash; аналітики можуть повторно запросити відгук по заявці, яку вже опитали, якщо потрібно.',
            'template_heading' => '<strong>Шаблон електронного листа</strong>',
            'template_body' => 'Вміст листа з опитуванням береться з наявної вкладки <strong>Шаблони листів</strong> &mdash; створіть шаблон із подією <strong>Опитування CSAT</strong> (нова подія поруч із <em>Заявку призначено</em> / <em>Заявку закрито</em>) і вставте код злиття <code>[csat_link]</code> туди, де ви хочете, щоб з\'явилося посилання для оцінювання. Стандартні коди злиття (<code>[requester_name]</code>, <code>[ticket_reference]</code>, <code>[analyst_name]</code>) доступні як звичайно.',
            'template_tip' => 'Якщо активний шаблон CSAT відсутній, кнопка <em>Відгук</em> відмовляє з чітким повідомленням про помилку, а автоматичний запуск мовчки пропускається &mdash; ви ніколи не створите недійсні посилання на опитування.',
            'survey_heading' => '<strong>Сторінка опитування</strong>',
            'survey_body' => 'Заявник натискає посилання в листі і потрапляє на сторінку без входу з вибором від 1 до 5 та необов\'язковим полем для коментаря. Два візуальні стилі, що налаштовуються в <strong>Налаштуваннях &rarr; CSAT</strong>:',
            'survey_stars' => '<strong>Зірки</strong> &mdash; класична поведінка заливки при наведенні з хвостом. Наведення на зірку №3 заповнює №1+№2+№3 золотим. Натисніть для фіксації.',
            'survey_emojis' => '<strong>Емодзі</strong> &mdash; 5 облич 😡 🙁 😐 🙂 😀 починаються в сірому масштабі з непрозорістю 40%; наведений або вибраний повертається до повного кольору в масштабі 1,25&times;. Натисніть для фіксації.',
            'survey_store' => 'Обидва режими зберігають одне й те саме число від 1 до 5, тому панелі керування та середні значення працюють однаково незалежно від обраного стилю. URL опитування є одноразовим &mdash; після того як користувач надіслав відповідь, те саме посилання відхиляє повторну відправку.',
            'chat_heading' => '<strong>Запит до клієнтів чату в самому чаті</strong>',
            'chat_body' => 'Якщо позначено <strong>Запитувати клієнтів чату в їхньому чаті</strong>, клієнта, який написав через WhatsApp, Telegram, Slack, Microsoft Teams чи Mattermost, питають у цьому чаті, а не електронною поштою &mdash; п\'ять кнопок у Telegram, Teams і Mattermost, &ldquo;відповідь однією цифрою&rdquo; в інших. Його відповідь потрапляє в ті самі результати, що й відповіді на опитування електронною поштою.',
            'chat_rules' => 'У WhatsApp питають лише поки відкрите 24-годинне вікно відповіді; поза ним, або якщо повідомлення в чаті не вдалося надіслати, використовується опитування електронною поштою. Цифра зараховується як оцінка лише одразу після запитання &mdash; у тому самому чаті, протягом тижня і до того, як клієнт написав щось інше &mdash; тож &ldquo;3&rdquo; у відповідь на запитання аналітика залишається повідомленням. Після оновлення вимкнено; для нової інсталяції ввімкнено.',
            'analytics_heading' => '<strong>Сторінка аналітики</strong>',
            'analytics_body' => 'Натисніть кнопку навігації ⭐ <strong>CSAT</strong> (між Графіком чергувань і Налаштуваннями), щоб відкрити аналітичну панель за адресою <code>tickets/csat/</code>. Вікно вибирається: 7 / 30 / 90 / 365 днів.',
            'card_kpi_title' => 'KPI-плитки',
            'card_kpi_body' => 'Середня оцінка (з 5), кількість відповідей, відсоток відповідей (відповіли ÷ надіслано)',
            'card_dist_title' => 'Розподіл оцінок',
            'card_dist_body' => 'Стовпчаста діаграма оцінок від 1 до 5 із точними кількостями та відсотками',
            'card_leader_title' => 'Рейтинг за аналітиками',
            'card_leader_body' => 'Середня оцінка + кількість відповідей на аналітика, впорядковані за спаданням середнього. Корисно для розмов про розвиток',
            'card_recent_title' => 'Останні відповіді',
            'card_recent_body' => 'Оцінки від найновіших, по 25 на сторінці, з вільними коментарями та клієнтом, який їх залишив, із посиланням на вихідну заявку',
            'analytics_filters' => 'Звужуйте сторінку фільтрами під заголовком: діапазон дат <strong>Від / До</strong> (замість кнопок днів), діапазон <strong>Оцінки</strong> (Позитивні 4-5, Нейтральні 3, Негативні 1-2), <strong>Аналітик</strong> і <strong>Клієнт</strong>. Аналітик і клієнт звужують кожну цифру на сторінці; діапазон оцінок звужує лише список відповідей, тож середнє значення й надалі має сенс. На телефоні фільтри сховано за кнопкою <strong>Фільтри</strong> внизу екрана. Сторінку з фільтрами можна додати в закладки.',
            'analytics_company' => 'Кожна цифра слідує за <strong>перемикачем компаній</strong> у заголовку: вибрана вами компанія або всі компанії, які ви бачите, за вибору <strong>Усі компанії</strong>.',
            'analytics_tip' => 'Прив\'язка до аналітика зберігається після перепризначення заявки, оскільки ID аналітика фіксується в рядку опитування під час надсилання, а не підтягується в реальному часі. Якщо заявку передавали між аналітиками перед закриттям, оцінку отримує аналітик, який її фактично закрив.',
            'one_heading' => '<strong>Одне опитування на заявку</strong>',
            'one_body' => 'Якщо увімкнено параметр <em>Одне опитування на заявку</em> (типово), повторно відкрита, а потім закрита заявка отримує ще одне опитування лише тоді, коли аналітик запускає його вручну &mdash; це запобігає спаму опитуваннями по нестабільній заявці, яка постійно циклується. Вимкніть, якщо хочете, щоб кожне закриття запускало нове опитування.',
        ],
        'users' => [
            'heading' => 'Управління користувачами',
            'intro' => 'Кнопка навігації <strong>Користувачі</strong> відкриває <code>tickets/users.php</code> &mdash; каталог кожного кінцевого користувача (людей, що подають заявки, а не аналітиків) разом з історією заявок кожного з них.',
            'p_intro' => 'Користувачі потрапляють у систему чотирма реактивними способами &mdash; самостійна реєстрація на порталі, вхідний лист від нового відправника, поштовий опитувач або рушій workflow, що створює запис із ініційованої заявки. Це покриває більшість випадків, але сторінка Користувачі також дозволяє <strong>попередньо створити</strong> користувача (наприклад, нового співробітника, якому ось-ось знадобиться доступ) і <strong>редагувати</strong> або <strong>видаляти</strong> наявні записи.',
            'add_heading' => '<strong>Додати користувача</strong>',
            'add_body' => 'Кнопка <strong>Додати</strong> в заголовку списку користувачів відкриває редактор особи. Це той самий редактор, що відкривається в <strong>Assets &rarr; Users</strong>, тож особу додають і змінюють однаково на будь-якому екрані:',
            'add_email' => '<strong>Електронна пошта</strong> &mdash; необов\'язкова, бо люди, які входять через каталог, можуть не мати поштової скриньки; їх знаходять за іменем входу. Вкажіть або адресу електронної пошти, або відображувану назву. Адреса має бути унікальною й не належати аналітику.',
            'add_names' => '<strong>Відображуване ім\'я / скорочене ім\'я</strong> &mdash; необов\'язково. Скорочене ім\'я &mdash; це те, яким ім\'ям користувач бачить вітання в листах (наприклад, <em>«Іван»</em> замість <em>«Іван Петренко»</em>).',
            'add_password' => '<strong>Пароль</strong> &mdash; необов\'язково. Якщо залишити поле порожнім, створюється обліковий запис <em>без пароля</em> &mdash; точно такий самий стан, у якому починають користувачі із вхідних заявок. Пізніше користувач може заявити права на обліковий запис через реєстрацію на порталі самообслуговування, встановивши власний пароль.',
            'add_details' => '<strong>Посада, відділ, офіс, телефон, мобільний, табельний номер і керівник</strong> &mdash; усе необов\'язкове й усе описує <em>особу</em>, а не обліковий запис. Варто заповнити: <strong>офіс</strong> підкаже, на якому майданчику хтось перебуває, перш ніж ви почнете його шукати, <strong>керівник</strong> фіксує лінію підпорядкування (введіть частину імені, щоб знайти), а <strong>табельний номер</strong> є ключем зв\'язку під час звірки із системою розрахунку зарплати, яка ніколи не чула про електронну пошту. Якщо ви імпортуєте з каталогу, усе це надходить уже заповненим. Адресна книга CardDAV заповнює все, крім табельного номера й керівника, яким у картці контакту немає куди зберігатися.',
            'managed_heading' => '<strong>Люди, які ведуться десь в іншому місці</strong>',
            'source_body' => '<strong>Звідки походить особа</strong> вказано в її даних (<em>Дані з: Contoso AD — довідник</em>), а фільтр <strong>Джерело</strong> під полем пошуку показує лише людей з одного довідника чи адресної книги, або лише тих, кого додано в FreeITSM, із кількістю біля кожного варіанта. Він з\'являється, щойно хоч когось пов\'язано з джерелом.',
            'add_book_body' => '<strong>Додати до адресної книги.</strong> Хтось, хто написав електронного листа, існує тут, але в жодній адресній книзі. Якщо адміністратор увімкнув <em>Дозволити аналітикам додавати людей до цієї адресної книги</em> (Система &rarr; Автентифікація, на адресній книзі), ця особа отримує кнопку <strong>Додати до адресної книги</strong> біля Редагувати. Спершу система запитує підтвердження, показуючи, що потрапить на картку, потім створює контакт і пов\'язує їх &mdash; це та сама людина, а не копія. Вона не додасть когось, чия електронна адреса вже є в книзі (натомість запустіть імпорт), і гарантує, що наступний імпорт підхопить новий контакт, або ж вилучить картку назад.',
            'managed_body' => 'Якщо особу імпортовано &mdash; з LDAP чи Active Directory, або з адресної книги CardDAV &mdash; дані, якими володіє це джерело, є <strong>лише для читання</strong>, і модальне вікно показує їх сірим. Джерело, звідки вони прийшли, є джерелом істини, і наступний імпорт перезаписав би все, що тут набрано, тому збереження одразу відхиляється, а не приймається з тихим відкатом через годину. <strong>Які саме</strong> дані залежить від джерела: довідник володіє всіма сімома, тоді як адресна книга — п\'ятьма &mdash; їй нема де зберігати табельний номер чи лінію підпорядкування, тож ці два поля залишаються для заповнення вами. А якщо в адресної книги увімкнено <em>запис змін назад</em>, жодне з полів не блокується: те, що ви вводите, надсилається до картки контакту, тож наступному імпорту нічого відкочувати. Усе інше в записі, включно з компанією і паролем, завжди можна редагувати.',
            'edit_heading' => '<strong>Редагування користувача</strong>',
            'edit_body' => 'Виберіть користувача зі списку, потім натисніть <strong>Редагувати</strong> у заголовку відомостей. Той самий редактор, уже заповнений. Збереження без пароля не змінює наявний хеш; якщо вказати пароль, його буде скинуто. Якщо керівник — хтось із компанії, яку ви не бачите, поле «Керівник» це повідомить, і керівник лишається як є, доки ви не виберете когось іншого.',
            'signin_body' => '<strong>Входить через</strong> показує, до якого провайдера єдиного входу прив\'язано особу. <strong>Від\'єднати</strong> поруч, після підтвердження, видаляє цей зв\'язок, тож наступний вхід почнеться заново &mdash; для того, хто перейшов до іншого провайдера або був прив\'язаний до не того облікового запису. Для людей, якими керує синхронізація каталогу, цього не пропонується, бо вона просто прив\'язала б їх знову.',
            'company_body' => '<strong>Компанія</strong> з\'являється, коли їх більше однієї. Для нової особи порожнє значення визначає компанію за її адресою електронної пошти; для наявної порожнє значення означає відсутність компанії, і її заявки потрапляють до сортування.',
            'managers_heading' => '<strong>Керівники</strong>',
            'managers_body' => 'Особу можна зробити <strong>керівником</strong> у порталі самообслуговування: вона отримує вкладку <strong>Заявки команди</strong> зі списком заявок людей, якими керує. Вона вимкнена, доки адміністратор не ввімкне її в <strong>System &rarr; Managers</strong>, де також вирішується, чи можуть керівники відповідати на ці заявки або закривати їх, і що вони бачать у конфіденційній (за замовчуванням нічого).',
            'managers_sources' => 'Керівником стають двома способами, обома одночасно: людина є <strong>Керівником</strong> у записах інших (вручну або з вашого каталогу) і для неї налаштовано <strong>лінії керування</strong>. Натисніть <strong>Доступ керівника</strong> поруч із Редагувати, щоб відкрити сторінку на весь екран для цієї особи, де можна дати їй усіх, окремих людей, групи людей, відділи або всю її лінію підпорядкування, і <strong>виключати</strong> людей &mdash; виключення завжди має пріоритет, у тому числі над полем «Керівник». Сторінка показує, скількох людей вона може бачити, і перелічує їх, розраховуючи так, ніби керівників уже ввімкнено, тож можна перевірити до ввімкнення. Натисніть будь-кого в цьому списку, щоб побачити, <strong>чому</strong> керівник може його бачити і як це припинити.',
            'managers_rules' => 'Керівник завжди бачить лише людей зі своєї компанії, ніколи себе і взагалі нікого, коли пішов з організації. Відділи зіставляються за назвою, введеною в записі кожної особи, тож перейменований відділ перестає збігатися &mdash; сторінка та System &rarr; Managers попереджають про рядок відділу, який нікому не відповідає. За замовчуванням лише адміністратори можуть змінювати лінії керування; System &rarr; Managers може відкрити це для будь-кого, хто може редагувати людей.',
            'delete_heading' => '<strong>Видалення користувача</strong>',
            'delete_body' => 'Кнопка <strong>Видалити</strong> є <strong>безпечною для FK</strong>: вона відмовляє, якщо користувач є заявником у будь-яких заявках або має записи в <code>users_assets</code>, повертаючи чітке повідомлення <em>«Неможливо видалити: цей користувач є заявником у N заявці(-ах). Спочатку перепризначте або закрийте ці заявки.»</em>. Історія аудиту ніколи не може мовчки зламатися.',
            'tip' => 'Усі поля модального вікна мають вимкнене автозаповнення браузера (зокрема <code>autocomplete="new-password"</code> для поля пароля), щоб збережені облікові дані аналітика не пропонувалися у формі, єдина мета якої — створення запису <em>іншої особи</em>.',
            'groups_heading' => '<strong>Групи</strong>',
            'groups_body' => 'Вкладка <strong>Групи</strong> поруч із <strong>Людьми</strong> містить іменовані групи людей &mdash; аналітиків і користувачів порталу самообслуговування разом в одній групі. Група створюється тут один раз, а потім використовується по всьому FreeITSM, тож можна надати їй доступ до теки бази знань або призначити навчальний курс, не створюючи той самий список двічі.',
            'groups_make' => '<strong>Створіть групу</strong> кнопкою <strong>Додати</strong> на вкладці Групи: назва та опис, який варто заповнити, адже наступній людині потрібно зрозуміти, для чого ця група.',
            'groups_add' => '<strong>Додавайте людей</strong>, шукаючи їх &mdash; пошук знаходить аналітиків і користувачів порталу разом, тож не потрібно знати, до якого типу належить особа.',
            'groups_expiry' => '<strong>Задайте членству дату завершення</strong>, коли доступ тимчасовий. Троє інженерів на об\'єкті на два тижні додаються з останнім днем і самі виходять із групи, коли він мине. Прострочене членство залишається у списку, позначене як прострочене, тож видно, у кого був доступ і до якого моменту.',
            'groups_uses' => '<strong>Для чого потрібна група:</strong> надання доступу до теки бази знань і призначення навчання LMS одразу групі людей. Зміни членства набувають чинності негайно &mdash; після цього нічого не потрібно застосовувати повторно.',
            'groups_admin' => '<strong>Групи бачить будь-хто з доступом до модуля Заявки; змінювати їх може лише адміністратор.</strong> Додавання когось у групу також може надати доступ до обмеженої теки бази знань, тож це надання доступу, а не просто впорядкування списків.',
        ],
        'dash' => [
            'heading' => 'Панель керування',
            'intro' => 'Панель керування заявками надає аналітику з одного погляду за допомогою настроюваних віджетів Chart.js. Кожен аналітик має власний макет панелі керування, тому ви можете зосередитися на показниках, важливих для вашої ролі &mdash; чи то особисте навантаження, пропускна здатність команди або відповідність SLA.',
            'step1' => '<strong>Відкрийте бібліотеку</strong> &mdash; натисніть «Редагувати панель», щоб увійти в режим редагування, потім перегляньте бібліотеку віджетів. Вибирайте із готових віджетів або створюйте власні, вибравши тип діаграми та властивість даних для агрегування.',
            'step2' => '<strong>Додайте віджети</strong> &mdash; натисніть кнопку + на будь-якому віджеті в бібліотеці, щоб додати його на свою панель. Він з\'являється негайно і починає відображати актуальні дані з вашої бази заявок.',
            'step3' => '<strong>Налаштуйте</strong> &mdash; натисніть іконку шестерні на будь-якому віджеті, щоб настроїти його назву, тип діаграми (стовпчаста, кругова, кільцева, лінійна, складена стовпчаста, багатолінійна), фільтр діапазону дат, фільтр відділу та часове групування (щоденно, щотижня, щомісяця).',
            'step4' => '<strong>Упорядкуйте</strong> &mdash; перетягуйте віджети для їх переупорядкування. Ваш макет зберігається для кожного аналітика, тому він зберігається між сесіями.',
            'examples' => 'Поширені приклади віджетів: <strong>Заявки за статусом</strong> (кільцева діаграма, що відображає відкриті, вирішені та закриті), <strong>Заявки за пріоритетом</strong> (стовпчаста діаграма обсягу за ступенем серйозності), <strong>Тижневий обсяг</strong> (лінійна діаграма відстеження нових заявок за часом) та <strong>Навантаження аналітиків</strong> (складена стовпчаста діаграма активних заявок кожного аналітика).',
            'tip' => 'Використовуйте фільтри діапазону дат на окремих віджетах для порівняння поточних показників із попередніми періодами. Наприклад, подання «Цей місяць проти минулого місяця» допомагає завчасно виявляти тенденції в обсязі заявок.',
        ],
        'cal_rota' => [
            'switch_note' => 'Не користуєтеся графіком чергувань? Вимкніть його в розділі <strong>Система &rarr; Модулі &rarr; Доступність &rarr; Функції заявок</strong> - сторінка, її налаштування та функція бота War Room <em>хто черговий</em> зникнуть, а нічого не видаляється.',
            'heading' => 'Календар &amp; графік чергувань',
            'intro' => 'Два інструменти планування допомагають вашій команді залишатися організованою: календар заявок, що візуалізує навантаження з плином часу, і графік чергувань персоналу для управління змінами та доступністю чергування.',
            'cal_heading' => '<strong>Подання у вигляді календаря</strong>',
            'cal_body' => 'Календар відображає кожну заявку, для якої встановлено <code>work_start_datetime</code> (через контекстне меню <em>Зафіксувати час</em> / <em>Запланувати</em>), у вигляді кольорового блоку в запланований час. Червоні блоки — пріоритет <em>Високий</em>, зелені — <em>Низький</em>, синій — все інше. Використовуйте кнопки <em>Сьогодні</em>, шеврони <em>&lt;</em> / <em>&gt;</em> і перемикач <strong>Місяць / Тиждень / День</strong> праворуч від заголовка для навігації &mdash; <em>Попередній</em> / <em>Наступний</em> переміщуються на місяць, тиждень або день залежно від активного подання.',
            'cal_scope' => '<strong>Моє або Усі.</strong> Календар відкривається на вашій власній запланованій роботі, з перемикачем <strong>Усі</strong> біля кнопок перегляду; ваш вибір запам\'ятовується. У режимі «Усі» кожна заявка має <strong>колір відповідального за неї</strong>, з легендою, що називає людей, які справді на екрані, і наведення на заявку показує, чия вона, без потреби відводити погляд. Нічого ні від кого не приховано &mdash; це ті самі заявки, які вже перелічені у вхідних.',
            'cal_edit' => '<strong>Перевпорядкування роботи.</strong> <strong>Перетягніть заявку</strong> на інший день чи час: у режимі перегляду місяця вона зберігає свій час, а в режимах тижня й дня вона отримує час, у який ви її відпустили, із прив\'язкою до найближчих 15 хвилин. Її тривалість ніколи не змінюється &mdash; перетягування означає <em>почати тоді</em>, а не <em>зробити довшою</em>. Або <strong>клацніть на заявці</strong>, щоб відкрити її, де можна змінити дату, час, тривалість і параметр «весь день», або повністю очистити розклад. Календар також <strong>оновлюється сам кожні кілька секунд</strong>, тож коли колега щось планує, це з\'являється без перезавантаження сторінки &mdash; і не оновлюється, поки у вас відкрита заявка або триває перетягування.',
            'cal_month' => '<strong>Подання «Місяць»</strong> &mdash; класична сітка з 6 рядків із заголовком дня тижня; кожна клітинка дня показує до трьох плиток заявок із їхнім часом початку, плюс посилання <em>+N ще</em>, що переводить вас у подання «День» для цієї дати. Сьогоднішній день виділено.',
            'cal_week' => '<strong>Вигляд тижня</strong> &mdash; Пн&ndash;Нд по горизонталі над 24-годинною вертикальною шкалою. Заявки відображаються у вигляді кольорових блоків завширшки 1 година на час початку. Стовпець сьогоднішнього дня виділено; заголовок дня тижня залишається на місці, поки прокручується сітка годин.',
            'cal_day' => '<strong>Вигляд дня</strong> &mdash; один високий стовпець для вибраного дня з тією самою 24-годинною шкалою. Заявки відображаються у вигляді більших блоків із <code>ticket_number &mdash; subject</code> та часом початку; натисніть, щоб відкрити деталі.',
            'rota_heading' => '<strong>Графік чергувань персоналу</strong>',
            'rota_body' => 'Сторінка графіка дозволяє керівникам команд і менеджерам планувати зміни аналітиків протягом тижня. Визначте стандартні робочі години, призначте чергування та відзначте свята або відсутність, щоб команда завжди знала, хто є у наявності.',
            'rota_step1' => '<strong>Перегляньте сітку графіка</strong> &mdash; графік відображає аналітиків по одній осі та дні по іншій, а блоки змін показують охоплення з першого погляду.',
            'rota_step2' => '<strong>Додайте або відредагуйте зміни</strong> &mdash; натисніть на клітинку, щоб призначити тип зміни (напр. Рання, Пізня, Нічна, Чергування). Зміни зберігаються одразу.',
            'rota_step3' => '<strong>Плануйте наперед</strong> &mdash; переміщайтесь вперед по тижнях, щоб заздалегідь скласти графік. Це забезпечує достатнє покриття в відомі напружені періоди, святкові дні чи дні навчання.',
            'rota_step4' => '<strong>Заповніть кілька комірок одразу</strong> &mdash; <strong>клацніть правою кнопкою</strong> на комірці й оберіть <em>Копіювати</em>, щоб узяти зміну в ній, потім клацніть правою кнопкою на іншій і оберіть <em>Вставити</em>. Для кількох комірок <strong>перетягніть виділення блоком</strong> (або клацайте комірки по одній із ctrl) і вставте в увесь набір. Наведення на <strong>заголовок дня</strong> підсвічує весь цей день, а наведення на <strong>ім\'я аналітика</strong> підсвічує весь його тиждень &mdash; клацніть правою кнопкою на будь-якому з них і вставте в усе виділене. Якщо в частині комірок уже є зміна, меню пропонує обидва варіанти простими словами &mdash; <em>Вставити в усі 7</em> і <em>Вставити в 6 порожніх комірок</em> &mdash; тож ви обираєте до того, як підтвердити, а не після. Перезапис просить підтвердження і повідомляє, скільки змін буде замінено; заповнення порожніх комірок відбувається одразу, адже нічого не втрачається. Ті самі меню також дають змогу <strong>очистити</strong> день, тиждень чи виділення, знову ж повідомляючи, скільки змін це видалить.',
            'rota_step5' => '<strong>Скопіюйте весь день або весь тиждень для однієї людини</strong> &mdash; клацніть правою кнопкою на <strong>заголовку дня</strong> й оберіть <em>Копіювати</em>, щоб зняти всі зміни цього дня, або на <strong>імені аналітика</strong>, щоб зняти весь його тиждень. Вставлення в інший день або на іншого аналітика робить їх однаковими: зміни, яких не було в копії, очищаються, тож ви отримуєте саме той день, що копіювали, а не суміш двох. День можна вставити лише в інший день, а аналітика — лише на іншого аналітика &mdash; день це одна зміна <em>на людину</em>, а тиждень це одна зміна <em>на день</em>, тож немає розумного способу накласти одне на інше. Спробуйте — і меню про це повідомить, і скаже, куди можна вставити натомість.',
            'rota_step6' => '<strong>Скопіюйте весь тиждень</strong> &mdash; <strong>Копіювати тиждень</strong> і <strong>Вставити тиждень</strong> у верхньому правому куті знімають усі зміни того тижня, який ви переглядаєте, і переносять їх на інший — це найшвидший спосіб побудувати повторюваний графік чергувань. Вставлення <em>замінює</em> цільовий тиждень, тож підтвердження повідомляє, скільки записів буде видалено. Це завжди стосується лише тих днів і людей, які сітка справді вам показує.',
            'tip' => 'Поєднуйте календар і графік чергувань для ефективного планування потужностей. Якщо у календарі відображається сплеск заявок кожного понеділка зранку, переконайтеся, що в графіку передбачено додаткове покриття на цей слот.',
        ],
        'settings' => [
            'heading' => 'Налаштування',
            'intro' => 'Сторінка налаштувань — це місце, де ви конфігуруєте будівельні блоки вашої системи тікетів. Усі довідкові значення, цілі SLA, інтеграція електронної пошти та настроювані поля керуються тут.',
            'sla_callout_title' => 'Управління SLA &mdash; повний посібник',
            'sla_callout_body' => 'Параметри конфігурації, бізнес-календарі, призупинення статусів, сповіщення про порушення, налаштування cron-завдань, а також приклади для команд в одному та різних часових поясах. Досить об\'ємно, щоб заслужити окрему сторінку.',
            'card_dept_title' => 'Відділи',
            'card_dept_body' => 'Створюйте відділи, наприклад ІТ, Кадри та Фінанси. Кожен відділ стає текою у вхідних та фільтром на панелі керування',
            'card_types_title' => 'Типи заявок',
            'card_types_body' => 'Визначте типи запитів, які обробляє ваша служба підтримки: Інцидент, Запит на обслуговування, Проблема, Зміна. Типи допомагають аналітикам класифікувати роботу',
            'card_type_rules_title' => 'Тип для нових заявок',
            'card_type_rules_body' => 'У розділі «Типи заявок» призначайте кожній новій заявці тип, коли ніхто його не вибрав: типовий, а перед ним - правила за способом надходження (електронна пошта, портал, веб-чат, телефон, моніторинг...), поштовою скринькою, джерелом, відділом, словами в темі або доменом ініціатора. Спрацьовує перше правило, що збіглося; «Спробувати» показує, який тип отримала б заявка',
            'card_priorities_title' => 'Пріоритети',
            'card_priorities_body' => 'Встановіть рівні пріоритету з назвами, кольорами та порядком сортування. Кожен пріоритет пов\'язується з цільовим показником SLA для реагування та вирішення',
            'card_statuses_title' => 'Статуси',
            'card_statuses_body' => 'Налаштуйте етапи життєвого циклу заявки. Стандартні статуси включають Новий, Відкритий, В роботі, В очікуванні, Вирішений та Закритий',
            'card_categories_title' => 'Категорії',
            'card_categories_body' => 'Групуйте заявки за технічними областями: Обладнання, Програмне забезпечення, Мережа, Доступ. Категорії забезпечують розбивку у звітах',
            'card_sla_title' => 'Цілі SLA',
            'card_sla_body' => 'Визначте цільові показники часу реагування та вирішення для кожного пріоритету. Таймери SLA відображаються на заявках і спричиняють попередження про порушення',
            'card_email_title' => 'Імпорт електронної пошти',
            'card_email_body' => 'Підключіть поштову скриньку (Exchange, Microsoft 365), щоб автоматично імпортувати листи як нові заявки. Відповіді підв\'язуються до наявних заявок',
            'card_custom_title' => 'Настроювані поля',
            'card_custom_body' => 'Додайте власні поля до заявок для даних, які вашій організації потрібно зафіксувати, але які не охоплені стандартним набором полів',
            'card_templates_title' => 'Шаблони електронних листів',
            'card_templates_body' => 'Налаштуйте шаблони сповіщень, що надсилаються кінцевим користувачам при створенні, оновленні, вирішенні заявок або для опитування CSAT. Вставляйте коди злиття, наприклад [requester_name] та [csat_link]',
            'card_checklists_title' => 'Чек-листи',
            'card_checklists_body' => 'Визначте, що відбувається, коли хтось закриває заявку, у якій ще залишилися невиконані обов\'язкові кроки чек-листа: <strong>попередити</strong> й зафіксувати внутрішню нотатку із зазначенням кроків і того, хто закрив заявку, або <strong>блокувати</strong> закриття, доки їх не виконано. Застосовується всюди, де заявку можна закрити - включно з масовими діями, REST API та автоматизацією робочих процесів',
            'card_custom_fields_title' => 'Додаткові поля',
            'card_custom_fields_body' => 'Створюйте додаткові відомості, потрібні для певного виду заявок, — текст, число, дату, так / ні, список із вашими власними варіантами, веб-адресу або адресу електронної пошти — і прив\'язуйте кожне до окремих типів заявок або до всіх. Кожне поле визначає, чи його потрібно заповнити <strong>під час реєстрації заявки</strong> (форма «Нова заявка», REST API і, якщо потрібно, портал), <strong>перед закриттям</strong> (згідно з правилом обов\'язкових полів) чи в обох випадках, а також чи <strong>запитують його в ініціатора</strong> на порталі — де з\'являється вибір типу заявки, щойно це змінює те, що запитується. Відповіді показуються на панелі властивостей заявки та в її історії. Зміна типу заявки приховує відповіді, яких немає в новому типі, але ніколи їх не видаляє',
            'card_mandatory_title' => 'Обов\'язкові поля',
            'card_mandatory_body' => 'Позначте поля, які мають бути заповнені перед закриттям заявки — категорія, код вирішення, відповідальний тощо. Потім оберіть, що станеться, коли хтось закриває заявку з порожнім полем: <strong>попереджати</strong>, <strong>попереджати й надсилати лист</strong> комусь, наприклад керівнику з надання послуг, або <strong>відмовляти</strong> в закритті. Окремий перемикач фіксує це на заявці як внутрішню нотатку. Поле, вимкнене для компанії, ніколи не є обов\'язковим, а об\'єднання заявок ніколи цього не запускає. Застосовується всюди, де заявку можна закрити — включно з масовими діями, REST API та автоматизацією процесів',
            'card_cleanup_title' => 'ШІ-очищення відповідей',
            'card_cleanup_body' => 'Ключ Anthropic + модель + тон для кнопки ✨ Cleanup в редакторі відповідей. Окремий ключ від інших функцій AI для деталізованого обліку витрат',
            'card_csat_title' => 'CSAT',
            'card_csat_body' => 'Режим надсилання (вимкнено / автоматично / вручну), затримка, захист один-на-заявку, шкала (зірки або смайли). Дивіться розділ 6 для повного опису процесу',
            'email_heading' => '<strong>Детальніше про імпорт електронної пошти</strong>',
            'email_body' => 'Функція імпорту пошти підключається до вашої спільної поштової скриньки та завантажує нові повідомлення як заявки. Коли кінцевий користувач надсилає лист на вашу адресу підтримки (напр. support@yourcompany.com), FreeITSM створює заявку з темою листа як заголовком та тілом листа як описом. Якщо відправник відповідає на лист-сповіщення, відповідь додається до наявної заявки, а не створює дублікат.',
            'email_step1' => '<strong>Налаштуйте поштову скриньку</strong> &mdash; перейдіть до Налаштувань та введіть облікові дані Exchange або Microsoft 365. Для безпечного підключення без пароля підтримується автентифікація OAuth.',
            'email_step2' => '<strong>Встановіть інтервал опитування</strong> &mdash; оберіть, як часто FreeITSM перевіряє поштову скриньку на нові повідомлення. Коротші інтервали означають швидше створення заявок.',
            'email_step3' => '<strong>Призначте значення за замовчуванням</strong> &mdash; встановіть відділ, тип та пріоритет за замовчуванням для заявок, створених з електронної пошти. Аналітики можуть змінити їх після імпорту.',
            'email_thread_note' => '<strong>Відповідь без номера заявки</strong> &mdash; кожен лист, який надсилає FreeITSM, містить номер заявки, тож відповідь на нього завжди знаходить свою заявку. Коли хтось натомість відповідає на <em>власний</em> перший лист (скажімо, щоб додати забуте вкладення), номера для пошуку немає, і за замовчуванням така відповідь створює нову заявку. Встановіть Заявки &rarr; Налаштування &rarr; Загальні &rarr; <strong>Відповідь без номера заявки</strong> у значення <strong>Приєднується до заявки, до якої належить її листування</strong>, і вона потрапить на заявку, яку відкрив той перший лист, відновлюючи її, якщо вона була закрита (коли відновлення ввімкнено). Зіставляються лише листи в тій самій поштовій скриньці.',
            'email_reply_to_note' => '<strong>Кому відповідає «Відповісти»</strong> &mdash; за замовчуванням поле відповіді адресовано особі з повідомлення, яке ви читаєте. Якщо до листування долучаються колеги ініціатора, а ви хочете завжди відповідати ініціатору, встановіть Заявки &rarr; Налаштування &rarr; Загальні &rarr; <strong>Відповідь надходить</strong> у значення <strong>Ініціатору заявки</strong>. Адресу завжди можна змінити перед надсиланням.',
            'email_sent_copy_note' => '<strong>Копія надісланої пошти в теці «Надіслані» (Basic IMAP)</strong> - поштова скринька Basic IMAP надсилає через SMTP, який не зберігає копії, тож той, хто читає цю саму скриньку в Thunderbird чи вебпошті, не бачив би, що надіслала служба підтримки. Відредагуйте скриньку та ввімкніть <strong>Зберігати копію надісланої пошти</strong>, одразу під <em>Використовувати вхід IMAP для надсилання</em>: тоді кожна відповідь, лист за шаблоном, лист процесу та системний лист, які вона надсилає, також потрапляє в її теку «Надіслані» як прочитаний. Внутрішні сповіщення аналітикам ніколи не архівуються. Залиште <strong>Теку «Надіслані»</strong> порожньою, щоб використовувати теку, яку ваш поштовий сервер позначає як «Надіслані», або введіть її назву. Залиште перемикач вимкненим, якщо ваш поштовий сервер уже зберігає надіслану пошту (Gmail і Microsoft 365 це роблять, як і деякі хостинг-компанії) - інакше ви отримаєте дві копії. <strong>Тест</strong> показує, до якої теки потрапила копія. Якщо копію не вдалося зберегти, лист усе одно надіслано, а причину наведено на вкладці <strong>Активність</strong> &rarr; <strong>Вихідні</strong> скриньки як <em>Копіювання в теку «Надіслані»</em>.',
            'tip' => 'Використовуйте шаблони електронних листів для підтримання професійного, послідовного тону в усіх комунікаціях з кінцевими користувачами. Шаблони підтримують динамічні заповнювачі для номера заявки, імені заявника, імені аналітика та статусу.',
            'closemsg_heading' => '<strong>Одноразове повідомлення під час закриття заявки</strong>',
            'closemsg_body' => 'Вставте <code>[ticket_closed_message]</code> будь-де в активному шаблоні <strong>Заявку закрито</strong>, і відтоді встановлення заявці статусу «закрито» запитуватиме в аналітика речення — <em>&ldquo;запасний зарядний пристрій на вашому столі&rdquo;</em>, <em>&ldquo;закрито за домовленістю по телефону&rdquo;</em>. Усе, що вони напишуть, потрапляє точно туди, де ви розмістили плейсхолдер, тож ви контролюєте формулювання навколо нього. Це не налаштування, і нічого не зберігається: одна нотатка, одна заявка, один лист. Якщо нічого не ввести, цього рядка просто не буде — без пропуску, без зайвої пунктуації.',
            'closemsg_note' => '<strong>Запит з\'являється, лише коли плейсхолдер справді є в шаблоні.</strong> Без нього все, що набрав аналітик, тихо викидалося б, а кожна служба підтримки, якій це не потрібно, отримала б зайвий клік на кожному закритті. Тож він вмикається сам, коли ви це налаштуєте, і не заважає, коли ви цього не робили.',
            'cat_heading' => '<strong>Категорії та два поля поруч з ними</strong>',
            'cat_body' => '<em>Тип</em> заявки визначає, що це за річ; <em>категорія</em> визначає, про що вона. Створіть список у розділі <strong>Налаштування &rarr; Категорії</strong> разом із перемикачами, які визначають, чи з\'являється щось із цього на заявці взагалі.',
            'cat_card_one_title' => 'Категорія',
            'cat_card_one_body' => 'Те, як заявку заявили, обране під час її створення. Заявка має рівно одну категорію, тож звіт за категоріями завжди дорівнює фактичній кількості заявок.',
            'cat_card_close_title' => 'Категорія при закритті',
            'cat_card_close_body' => 'Той самий список, запитаний ще раз, коли заявка завершується. Зазвичай аналітик просто підтверджує його &mdash; він виправдовує себе на тих заявках, де перше припущення було хибним, і саме так ви дізнаєтеся, що дванадцять із тридцяти семи «проблем із принтером» насправді були проблемою мережі.',
            'cat_card_res_title' => 'Код вирішення',
            'cat_card_res_body' => 'Як завершилася заявка, а не про що вона була &mdash; «Виправлено віддалено», «Проведено навчання», «Несправність не виявлено». Спочатку доступно десять розумних варіантів, і всі їх можна змінити.',
            'cat_rule_off' => '<strong>Усі три спочатку вимкнені.</strong> Спершу створіть свій список, потім увімкніть потрібні. Кожен можна налаштувати окремо для кожної компанії.',
            'cat_rule_levels' => 'Категорії можуть мати підкатегорії до трьох рівнів углиб, і жоден рівень не є обов\'язковим.',
            'cat_rule_type' => 'Категорію можна прив\'язати до одного типу заявки, тож «Введення користувача в посаду» пропонується лише для запиту на обслуговування. Прив\'язка належить категорії верхнього рівня, і її підкатегорії успадковують її.',
            'cat_rule_typechange' => '<strong>Зміна типу заявки очищає категорію, яка належала старому типу</strong>, і повідомляє про це на екрані. Категорія, не прив\'язана до жодного типу, переживає зміну.',
            'cat_rule_portal' => 'Позначте <em>Клієнти можуть обирати це</em>, щоб пропонувати категорію на порталі самообслуговування. Ініціатори бачать короткий список простою мовою, тоді як аналітики бачать усе дерево.',
            'cat_rule_retire' => 'Вимкніть категорію, щоб вивести її з ужитку &mdash; вона залишається на заявках, які вже її мають, і перестає пропонуватися на нових. Це майже завжди краще за видалення, яке відхиляється, поки нею щось ще користується.',
            'cat_rule_report' => 'Усі три можна відобразити на панелі заявок. Обидві діаграми категорій підсумовуються до верхнього рівня, а заявки без жодного значення враховуються як <em>Без категорії</em>, а не приховуються.',
            'cat_rule_workflow' => '<strong>Категорії в процесах:</strong> процес може маршрутизувати заявки за категорією - умова <em>Категорія</em> працює для кожного тригера заявки, а тригер <em>Змінюється категорія заявки</em> ловить заявку, категоризовану під час сортування. За замовчуванням умова з назвою категорії збігається також із її підкатегоріями, тож «Обладнання» охоплює «Обладнання &rarr; Ноутбук»; виберіть <strong>Збігається лише з цією категорією</strong> у <strong>Заявки &rarr; Налаштування &rarr; Категорії &rarr; Категорії в процесах</strong>, щоб кожен процес називав кожну потрібну підкатегорію. Коли зміна типу заявки очищає її категорію, тригер також спрацьовує.',
            'cat_tip' => 'Якщо не знаєте, з чого почати, залиште категорії порожніми й увімкніть лише <strong>Код вирішення</strong>. Це поле, яке найшвидше змінює те, що ви робите &mdash; якщо п\'ята частина ваших заявок повертається як «Проведено навчання», це проблема документації, а не ІТ.',
        ],
        'tips' => [
            'heading' => 'Швидкі поради',
            'search_title' => 'Шукайте все',
            'search_body' => 'Модальне вікно пошуку перевіряє номери заявок, теми, імена заявників та адреси електронної пошти. Використовуйте його для швидкого пошуку пов\'язаних заявок, коли користувач телефонує щодо існуючої проблеми.',
            'sla_title' => 'Стежте за SLA',
            'sla_body' => 'Таймери SLA відображаються на кожній заявці в панелі читання. Кольорові індикатори стають жовтими при наближенні до порушення та червоними при перевищенні цілі, щоб ви могли розставляти пріоритети відповідно.',
            'reply_title' => 'Відповідайте з вхідних',
            'reply_body' => 'Для відповіді кінцевому користувачу не потрібно відкривати поштовий клієнт. Використовуйте кнопку Відповісти в панелі читання, щоб надіслати повідомлення безпосередньо. Воно автоматично прив\'язується до заявки.',
            'reply_to_title' => 'Кому йде відповідь',
            'reply_to_body' => 'Відповідь адресується особі з повідомлення, яке ви читаєте. Якщо ви хочете, щоб вона завжди йшла ініціатору заявки, змініть <strong>Відповідь надходить</strong> у Заявки &rarr; Налаштування &rarr; Загальні. У будь-якому разі ви можете змінити адресу або додати людей у копію (Cc) перед надсиланням.',
            'trail_title' => 'Використовуйте журнал активності',
            'trail_body' => 'Перш ніж працювати над заявкою, прогортайте її журнал активності. Попередні нотатки аналітика, листи та зміни полів дають вам повний контекст, щоб ви не просили користувача повторювати інформацію.',
            'dash_title' => 'Панель керування для менеджерів',
            'dash_body' => 'Створіть панель керування з віджетами для показників відповідності SLA, середнього часу вирішення та заявок за відділами. Демонструйте її на нарадах команди для стимулювання постійного вдосконалення.',
            'rota_title' => 'Плануйте за графіком',
            'rota_body' => 'Заповнюйте графік чергувань щонайменше за два тижні наперед. У поєднанні з виглядом календаря це допомагає виявити прогалини в покритті до того, як вони стануть проблемою для часу реагування.',
            'drag_title' => 'Перетягуйте для сортування',
            'drag_body' => 'Перетягуйте заявки зі списку на теки для їх оновлення без відкриття. Підтеки відділів і статусів оновлюють обидва атрибути одночасно. Функція автоматичного розгортання дає змогу досягати вкладених статусів під час перетягування.',
            'dbl_title' => 'Подвійне клацання для повноекранного режиму',
            'dbl_body' => 'Одне клацання відкриває попередній перегляд заявки в панелі читання; подвійне відкриває її в повноекранному режимі для зосередженої роботи. Натисніть іконку розгортання поруч з темою для повернення назад.',
            'rightclick_title' => 'Правий клік для швидких дій',
            'rightclick_body' => 'Клацніть правою кнопкою на будь-якій заявці для зміни статусу, пріоритету або виконавця в один клік, а також для прив\'язки до CMDB та запису часу — не перемикаючись з поточної заявки.',
            'ai_title' => 'Дозвольте AI доопрацювати вашу відповідь',
            'ai_body' => 'Введіть чернетку (або просто тези) і натисніть <strong>✨ Cleanup</strong> &mdash; Claude переписує її як належний лист з привітанням, виправленням граматики та підписом. Посилання «Скасувати» з\'являється на 30 секунд.',
            'feedback_title' => 'Запитуйте зворотній зв\'язок',
            'feedback_body' => 'Увімкніть CSAT у розділі <strong>Налаштування &rarr; CSAT</strong>, щоб автоматично опитувати заявників після закриття їхніх заявок. Тенденції по аналітиках доступні за адресою <code>tickets/csat/</code> &mdash; цінно для розмов про розвиток.',
            'precreate_title' => 'Попередньо створюйте кінцевих користувачів',
            'precreate_body' => 'Кнопка навігації <strong>Користувачі</strong> дозволяє додати користувача до того, як йому знадобиться подати заявку &mdash; залиште поле пароля порожнім, і він зможе підтвердити обліковий запис через портал самообслуговування.',
        ],
        'companies' => [
            'heading' => 'Компанії та маршрутизація пошти',
            'intro' => 'Коли ваша інсталяція обслуговує більше однієї компанії (наприклад, ІТ-провайдер, що підтримує кількох клієнтів), заявки кожної компанії зберігаються окремо. Цей розділ пояснює, як вхідна пошта знаходить потрібну компанію.',
            'switcher_body' => 'У заголовку з\'являється <strong>перемикач компаній</strong>. Він визначає компанію, з якою ви зараз працюєте &mdash; список заявок, теки і лічильники показують лише її, і будь-яка створена вами заявка потрапляє саме до неї. Персонал із доступом до кількох компаній може перемикатися між ними; поточна компанія завжди показана, тож ви не можете відповісти в неправильному контексті. Керуйте самими компаніями в розділі <strong>Система &rarr; Компанії</strong>.',
            'mailboxes_heading' => 'Кожна поштова скринька належить до одного з двох видів &mdash; саме це визначає маршрутизацію:',
            'card_pinned_title' => 'Закріплена поштова скринька',
            'card_pinned_body' => 'Призначена для однієї компанії (наприклад, власна <code>itsupport@</code> клієнта). <strong>Уся</strong> пошта з неї потрапляє до цієї компанії &mdash; відправника ігнорують &mdash; і відповіді надсилаються з неї ж, тож клієнт бачить власну службу підтримки від початку до кінця.',
            'card_shared_title' => 'Спільна вхідна поштова скринька',
            'card_shared_body' => 'Одна адреса, що обслуговує багато компаній (наприклад, єдина <code>support@theprovider.com</code> провайдера). Вона не може визначити компанію лише за адресою, тож визначає її за тим, <strong>хто надіслав лист</strong>. Рекомендоване налаштування для провайдера з багатьма клієнтами.',
            'routing_heading' => 'Як спільна вхідна скринька обирає компанію',
            'routing_body' => 'Для кожного вхідного листа система перевіряє це по черзі, і перемагає перший збіг:',
            'flow_reply' => 'Відповідь на заявку',
            'flow_sender' => 'Відомий відправник',
            'flow_domain' => 'Відомий домен',
            'flow_triage' => 'Тріаж',
            'rule_reply' => '<strong>1. Відповідь на наявну заявку</strong> &mdash; розпізнана за номером, лист приєднується до цієї заявки і зберігає її компанію.',
            'rule_sender' => '<strong>2. Конкретна адреса відправника</strong>, прив\'язана до компанії (наприклад, <code>jane@gmail.com</code> &rarr; Acme) &mdash; ця компанія. Перевіряється раніше за домен, тож працює навіть для особистих/поштових вебадрес.',
            'rule_domain' => '<strong>3. Домен відправника</strong>, прив\'язаний до компанії (наприклад, будь-хто <code>@acme.com</code> &rarr; Acme) &mdash; ця компанія.',
            'rule_triage' => '<strong>4. Немає збігу</strong> &mdash; лист потрапляє в чергу <strong>тріажу</strong>, а не втрачається (див. нижче).',
            'keys_heading' => 'Домени та конкретні відправники (налаштовуються для кожної компанії в розділі Система &rarr; Компанії)',
            'keys_body' => 'Це ключі, за якими звіряється спільна вхідна скринька. Кожна компанія перелічує домени електронної пошти, якими володіє, і, за бажанням, окремі адреси відправників.',
            'card_domains_title' => 'Домени електронної пошти',
            'card_domains_body' => 'Домени, якими володіє компанія (acme.com, acme.co.uk). Будь-який відправник із зареєстрованого домену маршрутизується до цієї компанії. Домен належить лише одній компанії.',
            'card_senders_title' => 'Конкретні відправники',
            'card_senders_body' => 'Окремі адреси, прив\'язані до компанії, перевіряються раніше за домен. Використовуйте для фрилансера чи невеликого клієнта, який пише з особистої адреси.',
            'card_public_title' => 'Публічні провайдери',
            'card_public_body' => 'Gmail, Outlook, Yahoo та подібні не можна прив\'язати як домен (їх спільно використовує безліч непов\'язаних людей) &mdash; натомість прив\'яжіть точну адресу як конкретного відправника.',
            'triage_heading' => 'Черга тріажу &mdash; страхувальна сітка',
            'triage_body' => 'Коли лист зі спільної скриньки не збігається з жодною компанією, він потрапляє в <strong>Тріаж</strong> (доступний із перемикача компаній, з лічильником у реальному часі), а не втрачається. Кожен елемент показує відправника, домен, тему і скриньку, до якої він надійшов. Прив\'яжіть його до компанії в один крок:',
            'triage_create' => 'Оберіть наявну компанію або створіть нову на місці.',
            'triage_assign' => 'Для звичайного домену, за бажанням, <strong>спрямуйте цей домен</strong> до компанії; для публічної/поштової вебадреси, за бажанням, <strong>завжди прив\'язуйте цього відправника</strong> до неї.',
            'triage_sweep' => 'Будь-який із варіантів <em>прибирає все відразу</em>: він переміщує й усі інші листи в черзі з цього домену чи адреси, а також автоматично маршрутизує майбутню пошту &mdash; тож конкретного відправника потрібно розсортувати лише один раз.',
            'triage_tip' => 'Нічого ніколи не втрачається. Незіставлена пошта чекає в тріажі, доки хтось її не прив\'яже; тим часом неприв\'язана заявка все одно показується під компанією за замовчуванням.',
            'test_heading' => 'Перевірте маршрутизацію перед запуском',
            'test_body' => 'У розділі <strong>Система &rarr; Тест маршрутизації пошти</strong> можна змоделювати надходження листа &mdash; оберіть скриньку, введіть адресу відправника &mdash; і побачити, до якої саме компанії потрапила б нова заявка (або що вона пішла б у тріаж) і яке правило це вирішило. Це нічого не створює, лише читає ваші налаштування.',
            'settings_heading' => 'Налаштування: спільні за замовчуванням, індивідуальні там, де це важливо',
            'settings_body' => 'Деякі з цих налаштувань можна <strong>індивідуалізувати для кожної компанії</strong>; інші навмисно залишаються спільними. Там, де налаштування — це простий список варіантів &mdash; наприклад, <strong>типи заявок</strong> і <strong>джерела</strong> &mdash; перейдіть у контекст компанії, і ви побачите спільні значення за замовчуванням (кожне зі значком ока, щоб приховати те, чим вона не користується), а також усе, що вона додала лише для себе. Не можна сховати чи видалити варіант, поки його використовують відкриті заявки, а самі спільні значення за замовчуванням редагуються з MSP / компанії за замовчуванням.',
            'settings_custom_title' => 'Індивідуально для кожної компанії',
            'settings_custom_body' => 'Типи заявок і джерела (зараз), а також категорії, SLA та робочі години (незабаром) &mdash; речі, які справді відрізняються від клієнта до клієнта.',
            'settings_global_title' => 'Спільні для всіх компаній',
            'settings_global_body' => 'Статуси й пріоритети залишаються однаковими всюди, тож міжкомпанійна звітність і SLA залишаються узгодженими; так само команди, графік чергувань і поштові скриньки &mdash; ваша власна робота, а не клієнтська.',
            'allview_heading' => '<strong>Одна дошка для всіх компаній</strong>',
            'allview_body' => 'Перемикач компаній у заголовку має опцію <strong>Усі компанії</strong>. Кожна заявка, яку вам дозволено бачити, з\'являється в одному списку, і кожен рядок позначено компанією, якій він належить &mdash; корисно, коли ви підтримуєте кілька юридичних осіб і хочете єдиний огляд дня, не втрачаючи розуміння, що кому належить.',
            'allview_card_scope_title' => 'Не надає нічого нового',
            'allview_card_scope_body' => '«Усі» означає кожну компанію, до якої ви й так могли б дістатися по черзі. Аналітик, який підтримує дві з трьох ваших юридичних осіб, бачить саме ці дві, а аналітик з однією компанією бачить огляд лише цієї однієї компанії.',
            'allview_card_props_title' => 'Кожна юридична особа залишається окремою',
            'allview_card_props_body' => 'Відкрийте заявку — і її список типів, джерел, категорій та вирішень належить саме <em>тій</em> компанії &mdash; тож категорію, яка є в однієї юридичної особи, але відсутня в іншої, ніколи не можна застосувати до чужої заявки.',
            'allview_card_new_title' => 'Нові заявки запитують, яка компанія',
            'allview_card_new_body' => 'Немає єдиної активної компанії, яку можна припустити, і цей вибір визначає номер заявки, скриньку, з якої надсилаються відповіді, та застосовний SLA. Список типів заповнюється щойно ви зробите вибір.',
            'allview_rule_chip' => 'Заявка, що надійшла електронною поштою чи через портал і ще не маршрутизована, позначається як <strong>Немаршрутизована</strong>, а не показується під Компанією за замовчуванням, тож вона виділяється для тріажу.',
            'allview_rule_reply' => 'Відповіді все одно надсилаються зі скриньки, до якої надійшла заявка &mdash; це прив\'язано до заявки, а не до перегляду, тож об\'єднана дошка не може надіслати з неправильної адреси.',
            'allview_rule_knowledge' => '<strong>Запит до ШІ</strong> шукає в усіх компаніях, які ви бачите, поки увімкнено об\'єднаний перегляд, а не лише в одній. Статті, спільні для всіх компаній, включені в будь-якому разі.',
            'allview_rule_trash' => '<strong>Очищення кошика ніколи не поширюється на кілька компаній.</strong> Воно завжди застосовується лише до тієї однієї компанії, яку ви обирали останньою, адже «видалити все в кошику» одразу для кількох юридичних осіб — це не те, що хтось під цим має на увазі.',
            'allview_rule_other' => 'Розширюється лише список заявок. Активи, зміни, завдання й CMDB все одно показують по одній компанії за раз &mdash; перейдіть до потрібної компанії, щоб працювати з ними.',
            'privacy_heading' => 'Заявки кожної компанії залишаються приватними',
            'privacy_body' => 'Коли ви працюєте в контексті компанії, ви завжди бачите заявки лише <strong>цієї</strong> компанії &mdash; у списку, у пошуку, на панелях і на кожній заявці, яку відкриваєте (включно з її листами, вкладеннями, нотатками та історією). Співробітник може дістатися заявки, лише якщо йому надано доступ до її компанії (компанії кожного аналітика обираються в розділі Система &rarr; Аналітики, або доступ надається всій команді в Система &rarr; Команди), тож потрапити в дані іншого клієнта неможливо. Цей поділ забезпечується всюди за лаштунками, а не просто приховується з перегляду. На інсталяції з однією компанією це відбувається автоматично й непомітно &mdash; є лише одна компанія, тож усе просто належить їй.',
            'tip' => 'На інсталяції з однією компанією нічого з цього не з\'являється &mdash; є одна компанія, кожна заявка їй належить, і немає ні перемикача, ні тріажу. Ці функції вмикаються лише тоді, коли з\'являється друга компанія.',
        ],
    ],
    'help_sla' => [
        'page_title' => 'Керування SLA',
        'back_link' => '&larr; Назад до посібника з заявок',
        'sidebar_title' => 'Посібник SLA',
        'hero_title' => 'Управління SLA',
        'hero_sub' => 'Цілі реагування та вирішення з урахуванням робочих годин та сповіщення про порушення по відділах',
        'nav' => [
            'overview' => 'Огляд',
            'building_blocks' => 'Будівельні блоки',
            'behaviour_settings' => 'Параметри поведінки',
            'breach_notifications' => 'Сповіщення про порушення',
            'cron_setup' => 'Налаштування cron-завдання',
            'worked_examples' => 'Практичні приклади',
            'troubleshooting' => 'Усунення несправностей',
        ],
        'overview' => [
            'heading' => 'Огляд',
            'sub' => 'Що таке SLA, чому вони важливі та як на високому рівні працює рушій FreeITSM.',
            'p1' => 'Угода про рівень обслуговування (SLA) — це обіцянка щодо того, наскільки швидко ваша команда буде реагувати на заявку та вирішувати її. FreeITSM відстежує два таймери для кожної заявки: <strong>реагування</strong> (час від створення заявки до першої дії аналітика) та <strong>вирішення</strong> (час від створення заявки до її закриття). Обидві цілі встановлюються по пріоритету &mdash; тому P1 може мати 30 хвилин на реагування і 4 години на вирішення, тоді як P4 &mdash; 8 робочих годин і 5 робочих днів.',
            'switch_note' => 'Не користуєтеся SLA? Вимкніть SLA в розділі <strong>Система &rarr; Модулі &rarr; Доступність &rarr; Функції заявок</strong>: таймери, попередження про порушення та тригери процесів SLA зупиняються, а робочі календарі лишаються для годин роботи веб-чату. Повторне ввімкнення запитує, чи надіслати попередження, пропущені, поки його було вимкнено, чи пропустити їх.',
            'p2' => 'Рушій SLA FreeITSM має чотири принципові рішення, які варто розуміти:',
            'choice_business' => '<strong>Робочі години, а не астрономічний час.</strong> Заявка P2, подана о 16:30 з цільовим часом реагування 1 година, не порушить SLA о 17:30, якщо офіс закривається о 17:00. Таймер відновиться о 9:00 наступного робочого дня. Це галузевий стандарт і єдина справедлива модель, коли аналітики йдуть додому ввечері.',
            'choice_pause' => '<strong>Можна призупинити.</strong> Коли заявка перебуває в статусі з позначкою «Призупинити SLA» (наприклад, <em>Очікування відповіді</em> або <em>На утриманні</em>), таймер зупиняється. Він відновлюється, коли заявка переходить назад у робочий статус.',
            'choice_compute' => '<strong>Обчислення при читанні, а не збережений стан.</strong> Рушій перераховує стан SLA з журналу аудиту заявки кожного разу, коли ви на неї дивитесь. Немає збережених лічильників, які могли б розсинхронізуватись. Якщо ви пізніше змінюєте години бізнес-календаря, SLA кожної історичної заявки перераховується за новими годинами при наступному перегляді.',
            'choice_cutoff' => '<strong>Поріг застосування.</strong> Дата «Застосовувати SLA від» під контролем адміністратора означає, що наявні заявки у вашій системі не стануть раптово ретроактивно порушеними, коли ви вмикаєте SLA. Відстежуються лише заявки, створені в дату відсічення або після неї.',
            'tip' => 'Якщо ви новачок в ITIL: час реагування стосується підтвердження (хтось взяв це до роботи); час вирішення стосується завершення (проблема користувача виправлена). Два таймери йдуть незалежно і мають різні цілі.',
        ],
        'blocks' => [
            'heading' => 'Чотири будівельні блоки',
            'sub' => 'Налаштуйте ці чотири речі — і відстеження SLA запрацює. Все інше — це необов\'язкове вдосконалення.',
            'cal_heading' => '1. Бізнес-календарі',
            'cal_intro' => 'Календар визначає, коли ваша служба підтримки відкрита. Кожен календар має:',
            'cal_tz' => '<strong>Часовий пояс</strong> &mdash; ідентифікатор часового поясу IANA (напр. <code>Europe/London</code>, <code>America/New_York</code>, <code>Asia/Singapore</code>). Переходи на літній час обробляються автоматично.',
            'cal_hours' => '<strong>Щотижневі робочі години</strong> &mdash; один рядок на день тижня з прапорцем «Відкрито» та часом початку / закінчення. Нові календарі типово налаштовані на Пн–Пт 09:00–17:00, Сб/Нд — закрито. Рядок без позначки «Відкрито» означає, що служба підтримки в цей день не працює.',
            'cal_holidays' => '<strong>Свята</strong> &mdash; дата + необов\'язкова назва. Свята замінюють щотижневий шаблон (служба підтримки закрита, навіть якщо день випадає на понеділок).',
            'cal_default' => '<strong>Прапорець за замовчуванням</strong> &mdash; рівно один календар є типовим. Нові пріоритети успадковують його, якщо ви не вказуєте інший.',
            'cal_outro' => 'Ви можете створювати скільки завгодно календарів &mdash; по одному на офіс, на команду, для VIP-клієнтів із розширеним розкладом. Вони спільні для цілей SLA та рушія перевірки порушень.',
            'prio_heading' => '2. Пріоритети з цілями SLA',
            'prio_intro' => 'На вкладці «Пріоритети» (або через таблицю «Цілі SLA» на вкладці SLA) кожен пріоритет може мати:',
            'prio_response' => '<strong>Ціль реагування (хвилини)</strong> &mdash; скільки часу до першої дії аналітика.',
            'prio_resolution' => '<strong>Ціль вирішення (хвилини)</strong> &mdash; скільки часу до закриття заявки.',
            'prio_calendar' => '<strong>Календар</strong> &mdash; за яким бізнес-календарем йде таймер цього пріоритету. Залиште порожнім, щоб використовувати типовий календар.',
            'prio_outro' => 'Якщо обидва поля цілей залишити порожніми, відстеження SLA для цього пріоритету повністю вимикається &mdash; корисно для пріоритету «Інформаційний» або «Резерв», де немає часового тиску.',
            'pause_heading' => '3. Статуси із призупиненням SLA',
            'pause_intro' => 'На вкладці «Статуси» є спеціальний стовпець «Призупинити SLA». Позначте будь-який статус, що означає блокування заявки через щось поза контролем команди. Стандартні варіанти:',
            'pause_awaiting' => '<strong>Очікування відповіді</strong> &mdash; клієнт зобов\'язаний надати інформацію. Майже повсюдно визнається справедливою паузою.',
            'pause_vendor' => '<strong>На утриманні (Постачальник)</strong> &mdash; очікування підтримки від Microsoft / третьої сторони.',
            'pause_change' => '<strong>На утриманні (Вікно змін)</strong> &mdash; заплановано на майбутнє вікно технічного обслуговування.',
            'pause_parts' => '<strong>На утриманні (Комплектуючі)</strong> &mdash; очікування доставки обладнання.',
            'pause_warn' => 'Загальний статус «На утриманні» може зловживатися як клапан уникнення SLA, коли заявка складна або аналітик зайнятий. Якщо ваша команда дисциплінована — це нормально. Якщо ні, розгляньте заміну його конкретнішими варіантами вище або покладайтеся на панель <strong>Watchtower</strong>, яка позначає заявки, що перебувають у паузі понад 24 години, жовтим попередженням.',
            'cutoff_heading' => '4. Поріг застосування (<code>Enforce SLAs from</code>)',
            'cutoff_p1' => 'Найважливіше глобальне налаштування. Поки ви не встановите тут дату й час, відстеження SLA повністю вимкнено &mdash; жодні таймери не йдуть, жодні значки не відображаються у вхідних, жодні листи про порушення не надсилаються. Встановлення минулої дати вмикає SLA ретроактивно з цього моменту. Встановлення майбутньої дати планує вмикання.',
            'cutoff_p2' => 'Більшість команд встановлюють це значення на «зараз», коли вперше вмикають SLA &mdash; наявні заявки зберігають свій стан до SLA, а нові заявки з цього моменту відстежуються.',
        ],
        'behaviour' => [
            'heading' => 'Параметри поведінки',
            'sub' => 'Вони контролюють, як рушій реагує на крайні випадки. Значення за замовчуванням розумні &mdash; вам потрібно переглянути їх лише за наявності конкретних уподобань.',
            'prio_heading' => 'При зміні пріоритету в процесі роботи',
            'prio_intro' => 'Якщо заявку P3 підвищено до P1 наприкінці (бо проблема виявилася серйознішою), існують три розумні варіанти поведінки:',
            'prio_forward' => '<strong>Продовження (за замовчуванням)</strong> &mdash; зберегти накопичені робочі хвилини і просто перерахувати ціль. Якщо заявка використала 2 год з 8-годинної цілі P3, тепер вона має 2 год використання відносно 1-годинної цілі P1 &mdash; що означає вже порушення. Можна стверджувати, що це правильно: проблема БУЛА P1 весь цей час, команда просто не усвідомлювала.',
            'prio_recompute' => '<strong>Перерахунок</strong> &mdash; скинути таймер і застосувати нову ціль ретроактивно від моменту створення заявки. Чистий перерахунок.',
            'prio_reset' => '<strong>Скидання</strong> &mdash; почати новий таймер з моменту зміни пріоритету. Найм\'якший варіант для команди, але клієнти можуть почуватися обдуреними, якщо заявка з високим пріоритетом раптово отримує новий довгий таймер.',
            'reopen_heading' => 'При повторному відкритті закритої заявки',
            'reopen_intro' => 'Якщо заявка знову відкривається (користувач відповідає після закриття):',
            'reopen_reset' => '<strong>Скидання (за замовчуванням)</strong> &mdash; запустити новий таймер реагування та вирішення з моменту повторного відкриття. Розглядати повторне відкриття як фактично нову заявку.',
            'reopen_continue' => '<strong>Продовження</strong> &mdash; відновити з часу, що минув на момент закриття. Первинні цілі SLA продовжують діяти.',
            'first_heading' => 'Визначення першої відповіді',
            'first_intro' => 'Що вважається «першою відповіддю» &mdash; момент, що зупиняє таймер реагування?',
            'first_either' => '<strong>Будь-яка дія (за замовчуванням)</strong> &mdash; перша дія аналітика будь-якого роду: вихідний лист, зміна статусу, призначення.',
            'first_status' => '<strong>Зміна статусу</strong> &mdash; зараховується лише зміна статусу зі стандартного. Суворіше &mdash; аналітик має фактично попрацювати над заявкою, а не просто натиснути на неї.',
            'first_email' => '<strong>Вихідний лист</strong> &mdash; зараховується лише відповідь листом заявнику. Найсуворіше &mdash; клієнт повинен почути від нас.',
            'warn_heading' => 'Відсоток порогу попередження',
            'warn_body' => 'Наскільки далеко виконання цілі SLA до того, як індикатор змінюється із зеленого на жовтий. За замовчуванням 80% &mdash; тому при цілі реагування 60 хвилин жовтий колір з\'являється після 48 хвилин. Також керує сповіщеннями про порушення при спрацюванні попередження.',
        ],
        'breach' => [
            'heading' => 'Сповіщення про порушення',
            'sub' => 'Налаштовувані поштові правила по відділах, що спрацьовують при наближенні SLA до порушення (попередження) або фактичному порушенні.',
            'intro' => 'Кожне правило має чотири виміри, всі незалежні:',
            'scope_heading' => '1. Область застосування',
            'scope_body' => 'Або <strong>За замовчуванням</strong> (правило застосовується до заявок у кожному відділі), або <strong>конкретний відділ</strong>. Вирішення: правило, специфічне для відділу, має пріоритет над типовим для заявок цього відділу. Без типового правила відділи без конкретного правила не отримують сповіщень.',
            'trigger_heading' => '2. Тригер',
            'trigger_body' => 'Або <strong>Попередження</strong> (заявка перевищила поріг попередження &mdash; можливе порушення), або <strong>Порушення</strong> (заявка перевищила свою ціль &mdash; фактичне порушення). Кожен є окремим правилом, тому ви можете сповіщати різних людей для кожного.',
            'target_heading' => '3. Ціль',
            'target_body' => 'Який таймер відстежувати &mdash; <strong>Реагування</strong>, <strong>Вирішення</strong> або <strong>Обидва</strong>.',
            'recip_heading' => '4. Отримувачі',
            'recip_intro' => 'Будь-яка комбінація з:',
            'recip_assignee' => '<strong>Виконавець заявки</strong> &mdash; аналітик, який наразі веде заявку. Пропускається, якщо заявка не призначена.',
            'recip_teams' => '<strong>Члени команд відділу заявки</strong> &mdash; кожен аналітик у будь-якій команді, пов\'язаній із відділом заявки. Охоплює всю чергу без підтримки списку розсилки.',
            'recip_specific' => '<strong>Конкретний аналітик</strong> &mdash; шаблон «чемпіон SLA» / «менеджер з обслуговування», коли це конкретна людина, а не роль.',
            'recip_custom' => '<strong>Довільні адреси електронної пошти</strong> &mdash; вільний текст, розділений комами. Корисно для спільних поштових скриньок (<code>sla-alerts@company.com</code>), мостів до Slack/Teams або списків розсилки.',
            'tip' => 'Кожна заявка надсилає щонайбільше один лист на (ціль, тригер) &mdash; виконавець cron відстежує відправлені у таблиці <code>sla_notifications_sent</code>. Тому попередження спрацьовує один раз, порушення спрацьовує один раз — і більше нічого &mdash; без спамових циклів.',
            'warn' => '<strong>Немає правил = немає листів.</strong> Навіть якщо кожна заявка в системі порушена, нічого не спрацьовує, поки ви не додасте хоча б одне правило. Почніть з пари «За замовчуванням» — Попередження + Порушення, щоб охопити все.',
        ],
        'cron' => [
            'heading' => 'Налаштування cron-завдання',
            'sub' => 'Скрипт перевірки порушень має виконуватися за розкладом. Оптимальна частота — раз на 5 хвилин.',
            'p1' => 'Видимі у інтерфейсі індикатори SLA (значки у вхідних, панелі у вікні читання) обчислюються на льоту при завантаженні сторінки. Але листи про порушення можуть надсилатися лише якщо <em>щось</em> проактивно перевіряє заявки навіть тоді, коли ніхто на них не дивиться. Цим «чимось» є заплановане завдання &mdash; у Windows це Планувальник завдань; у Linux &mdash; cron.',
            'p2' => 'Скрипт — це <code>cron/sla_breach_check.php</code> у директорії встановлення FreeITSM. Його можна викликати двома способами:',
            'cli_heading' => 'A. CLI (рекомендовано на сервері, яким ви керуєте)',
            'cli_note' => 'Автентифікація не потрібна &mdash; дозволи файлової системи вже контролюють, хто може його запустити.',
            'http_heading' => 'B. HTTP (для спільного хостингу або зовнішніх планувальників)',
            'http_note' => 'Токен автоматично генерується при першому встановленні і зберігається в <code>system_settings</code> під ключем <code>sla_cron_token</code> (32 шістнадцяткові символи, ~128 біт ентропії). Знайдіть свій за допомогою:',
            'win_heading' => 'Планувальник завдань Windows',
            'win_intro' => 'Відкрийте Планувальник завдань (<code>taskschd.msc</code>) і створіть нове завдання з такими параметрами:',
            'tbl_field' => 'Поле',
            'tbl_value' => 'Значення',
            'win_r1_k' => 'Ім\'я',
            'win_r1_v' => 'FreeITSM &mdash; SLA Breach Check',
            'win_r2_k' => 'Виконувати незалежно від входу користувача',
            'win_r2_v' => 'Позначте це',
            'win_r3_k' => 'Тригер',
            'win_r3_v' => 'Щодня, повторювати кожен 1 день, повторення кожні 5 хвилин протягом 1 дня',
            'win_r4_k' => 'Дія',
            'win_r4_v' => 'Запустити програму',
            'win_r5_k' => 'Програма/скрипт',
            'win_r5_v' => '<code>C:\\wamp64\\bin\\php\\php8.2.x\\php.exe</code>',
            'win_r6_k' => 'Додати аргументи',
            'win_r6_v' => '<code>C:\\wamp64\\www\\freeitsm-app\\cron\\sla_breach_check.php</code>',
            'win_r7_k' => 'Запустити в',
            'win_r7_v' => '<code>C:\\wamp64\\www\\freeitsm-app</code>',
            'linux_heading' => 'Linux cron',
            'linux_intro' => 'Додайте один рядок до вашого crontab (<code>crontab -e</code>):',
            'sec_heading' => 'Безпека &mdash; що захищає HTTP-ендпоінт',
            'sec_intro' => 'Три рівні, всі застосовуються автоматично:',
            'sec_token' => '<strong>1. Токен спільного секрету</strong> &mdash; 128-бітний випадковий на кожну інсталяцію, порівнюється з постійним часовим зіставленням для запобігання атакам за часом.',
            'sec_lockout' => '<strong>2. Блокування невдалої автентифікації по IP</strong> &mdash; більше 10 спроб із неправильним токеном з одного IP за минулу годину спричиняє 1-годинне блокування 429. Захищає від перебору без потреби у fail2ban.',
            'sec_interval' => '<strong>3. Мінімальний інтервал між успішними запусками</strong> &mdash; <code>sla_cron_min_interval_seconds</code> (за замовчуванням 30 с). Навіть запит із дійсним токеном отримує відповідь 429, якщо він надходить раніше, ніж через цей час після останнього успішного запуску. Захищає від випадкового подвійного планування та нескінченних циклів.',
            'log_heading' => 'Журнал активності',
            'log_body' => 'Кожен виклик (прийнятий або відхилений) реєструється в таблиці <code>sla_cron_runs</code> з часом, результатом, кількістю та IP-адресою клієнта. Переглядайте останні 20 запусків на панелі <strong>Активність Cron</strong> внизу вкладки налаштувань SLA &mdash; корисно для перевірки спрацювання розкладу та аудиту невдалих спроб автентифікації. Рядки автоматично видаляються через <code>sla_cron_log_retention_days</code> днів (за замовчуванням 30), щоб таблиця залишалася компактною.',
        ],
        'examples' => [
            'heading' => 'Практичні приклади',
            'sub' => 'Від простого випадку одного часового поясу до складнішого міжчасового, де «справедливість» потребує визначення.',
            'ex1_heading' => 'Приклад 1: Заявка подана у Великій Британії, служба підтримки у Великій Британії',
            'ex1_title' => 'Простий випадок',
            'ex1_tag' => 'один часовий пояс',
            'ex1_setup' => '<strong>Налаштування:</strong> Один бізнес-календар під назвою <em>UK Office</em> з часовим поясом <code>Europe/London</code>, Пн–Пт 09:00–17:00, без свят. Пріоритет P2 має ціль реагування 1 година та ціль вирішення 4 години, обидві за календарем <em>UK Office</em>.',
            'ex1_scenario' => '<strong>Сценарій:</strong> Користувач подає заявку P2 о <strong>16:30 у Великій Британії в середу</strong>.',
            'ex1_timeline' => 'Ср 16:30 UK &mdash; <strong>заявку створено</strong>, таймер реагування запущено.
Ср 17:00 UK &mdash; офіс закривається, таймер призупинено (30 хв із 60 хв використано).
Чт 09:00 UK &mdash; офіс відкривається, таймер відновлено.
Чт 09:30 UK &mdash; аналітик відповідає. SLA реагування виконано в останній момент (60 хв використано, ціль 60 хв).',
            'ex1_outro' => 'Якби аналітик не відповів до <strong>четвер 10:00 UK</strong>, реагування <strong>порушило б SLA на 30 хвилин</strong> (90 хв використано проти цілі 60 хв &mdash; 30 із середовища ввечері, 60 із четвергового ранку). Годинний таймер тікає лише в робочі години, але заявка наприкінці дня все одно з\'їдає більшу частину свого бюджету вночі, коли офіс відкривається знову &mdash; аналітику, що приходить о 09:00, легко здатись, що у нього є повна година, тоді як насправді залишилося лише 30 хвилин.',
            'ex2_heading' => 'Приклад 2: Заявка подана у Великій Британії, служба підтримки в Естонії',
            'ex2_title' => 'Міжчасовий випадок',
            'ex2_tag' => '3 способи визначити «справедливість»',
            'ex2_setup' => '<strong>Налаштування:</strong> Клієнти у Великій Британії (<code>Europe/London</code>, GMT/BST), служба підтримки в Естонії (<code>Europe/Tallinn</code>, EET/EEST &mdash; <strong>на 2 години попереду Великої Британії</strong>). Обидві служби номінально працюють 09:00–17:00 місцевого часу.',
            'ex2_scenario' => '<strong>Сценарій:</strong> Клієнт з Великої Британії подає заявку P2 о <strong>16:30 UK у п\'ятницю</strong> (= 18:30 за Естонією, після закриття естонського офісу). Наступна можливість для аналітика в Естонії попрацювати над нею — понеділок 09:00 за Естонією (= 07:00 UK). Ціль реагування — 1 година.',
            'ex2_question' => 'Що повинен показувати SLA? Існують три обґрунтовані відповіді, кожна справедлива по-своєму. Ви обираєте, який календар призначити пріоритету, виходячи з того, що обіцяє ваш договір про обслуговування.',
            'optA_label' => 'Варіант A &mdash; Орієнтований на клієнта',
            'optA_p1' => '<strong>Встановіть для пріоритету календар з годинами <em>Великої Британії</em>.</strong> Таймер тікає за розкладом UK 09:00–17:00, незалежно від місцезнаходження аналітика.',
            'optA_p2' => 'У наведеному вище сценарії заявка подана о 16:30 UK у п\'ятницю: таймер йде з 16:30 до 17:00 UK п\'ятниці (30 хв використано), призупиняється на ніч + вихідні, відновлюється Пн 09:00 UK. Якщо аналітик в Естонії відповідає о 10:00 за Естонією в понеділок (= 08:00 UK), британський календар ще на паузі (офіс UK відкривається о 09:00 UK), тому додаткові хвилини не тікають &mdash; витрати залишаються 30 хв. <strong>SLA виконано з запасом 30 хв</strong>. Будь-яка відповідь після 09:30 UK (= 11:30 за Естонією) призведе до порушення.',
            'optA_p3' => '<em>Справедливо для:</em> клієнта. Їхній досвід відповідає їхньому робочому дню.<br><em>Компроміс:</em> Від аналітиків в Естонії очікується доступність з 09:00 до 17:00 UK (= з 11:00 до 19:00 за Естонією), що подовжує їхній робочий день на 2 години.',
            'optB_label' => 'Варіант B &mdash; Орієнтований на аналітика',
            'optB_p1' => '<strong>Встановіть для пріоритету календар з годинами <em>Естонії</em>.</strong> Таймер тікає за розкладом Естонія 09:00–17:00.',
            'optB_p2' => 'Той самий сценарій: заявка подана о 18:30 за Естонією в п\'ятницю (після закриття), таймер призупинено на вихідні, починає тікати Пн 09:00 за Естонією (= 07:00 UK). Якщо аналітик відповідає о 09:30 за Естонією в понеділок (= 07:30 UK), SLA реагування використав 30 хв із цілі 60 хв &mdash; <strong>виконано з запасом 30 хв</strong>. Клієнт з UK подав заявку о 16:30 UK у п\'ятницю і отримав відповідь о 07:30 UK у понеділок &mdash; їхній астрономічний час очікування значно перевищує те, що показує SLA.',
            'optB_p3' => '<em>Справедливо для:</em> аналітиків. Вони працюють у звичайні години.<br><em>Компроміс:</em> Клієнти у Великій Британії можуть відчувати, що SLA «бреше», якщо заявку, подану в п\'ятницю вдень, не підтверджено до ранку понеділка за естонським часом, але у звіті написано, що SLA реагування — 1 година. Переконайтеся, що у вашому договорі про обслуговування чітко зазначено, що SLA відраховується за годинами служби підтримки.',
            'optC_label' => 'Варіант C &mdash; Вікно перетину (найсуворіший)',
            'optC_p1' => '<strong>Встановіть для пріоритету календар, що охоплює лише ті години, коли обидві служби відкриті.</strong> UK 09:00–17:00 перетинається з Естонія 09:00–17:00 (= UK 07:00–15:00) у <strong>вікні UK 09:00–15:00</strong> &mdash; 6 годин на робочий день.',
            'optC_p2' => 'Той самий сценарій: заявка подана о 16:30 UK у п\'ятницю (поза вікном перетину, оскільки воно закривається о 15:00 UK), таймер призупинено на вихідні, відновлюється Пн 09:00 UK (= 11:00 за Естонією, момент відкриття вікна перетину). Якщо аналітик Естонії відповідає о 11:30 за Естонією (= 09:30 UK), SLA реагування використав 30 хв із цілі 60 хв &mdash; <strong>виконано з запасом 30 хв</strong>. Відповідь відбулася у вікні перетину, тому зараховується одразу.',
            'optC_p3' => '<em>Справедливо для:</em> обох сторін &mdash; SLA тікає лише в ті години, коли служба підтримки могла реально просунутися у вирішенні заявки, а клієнт є за своїм робочим місцем, щоб отримати відповідь.<br><em>Компроміс:</em> Коротше щоденне вікно означає довший астрономічний час для виконання агресивних цілей. Ціль вирішення 4 години охоплює 1,5 дні вікна перетину, тоді як при звичайному 8-годинному календарі вона б виконувалась у межах одного дня.',
            'choose_tip' => '<strong>Як обрати:</strong> Подивіться на ваш договір про обслуговування. Якщо там сказано «відповідь протягом 1 години з моменту отримання» &mdash; це Варіант A (годинник клієнта). Якщо «відповідь протягом 1 робочої години» &mdash; це зазвичай Варіант B (яка б служба не працювала). Якщо «протягом 1 години взаємної доступності» &mdash; це Варіант C. Якщо договору немає, запитайте команду: чи хочете ви відчувати тиск поза годинами Естонії (Варіант A), чи ви хочете, щоб клієнти у Великій Британії іноді почувалися проігнорованими (Варіант B)?',
            'ex3_heading' => 'Приклад 3: Призупинення таймера під час очікування постачальника',
            'ex3_title' => 'Як статуси паузи працюють на практиці',
            'ex3_tag' => 'призупинення таймера',
            'ex3_setup' => '<strong>Налаштування:</strong> Пріоритет P3 з ціллю вирішення 8 робочих годин, британський календар, статус «Очікування постачальника» позначений як <em>Призупинити SLA</em>.',
            'ex3_scenario' => '<strong>Сценарій:</strong> Заявку подано Пн 09:00 UK. Аналітик ескалює до Microsoft Пн 11:00 UK і переводить заявку в «Очікування постачальника». Microsoft відповідає Ср 14:00 UK. Аналітик впроваджує виправлення і закриває заявку Чт 10:00 UK.',
            'ex3_timeline' => 'Пн 09:00 &mdash; заявку створено, таймер вирішення запущено.
Пн 11:00 &mdash; переведено в "Очікування постачальника", <strong>таймер призупинено</strong> (2 год використано).
Ср 14:00 &mdash; переведено назад в "В роботі", <strong>таймер відновлено</strong>.
Ср 17:00 &mdash; офіс закривається (5 год використано загалом).
Чт 09:00 &mdash; офіс відкривається.
Чт 10:00 &mdash; заявку закрито (6 год використано загалом). <strong>SLA виконано</strong> при цілі 8 год.',
            'ex3_outro' => 'Астрономічний час: ~3 дні. Час SLA: 6 робочих годин. Без позначки статусу паузи SLA рахував би всі 2 дні очікування постачальника + робочі години, що становило б ~18 робочих годин &mdash; значно більше порогу порушення.',
